// Une seule ligne d'export : la copie dans n8n (n8n/build_*.py) retire les lignes qui commencent par « module.exports ».
// Lecture À LA DEMANDE de Google pour l'écran Résultats (n8n/renom-resultats-google.json) et pour le bilan mensuel (n8n/renom-bilan-mensuel.json).
// Recopié tel quel dans les nœuds Code de ces workflows (n8n/build_maj_membre.py) ; testé par moteur/tests/test_lecture_google.js
// et, pour le score, comparé au calcul Python (moteur/audit/piliers.py) par moteur/tests/test_lecture_google_parite.py.
//
// RIEN de ce qui sort d'ici n'est écrit dans la base : les valeurs vont dans la réponse HTTP à l'espace, ou dans l'email du bilan.
// Règles suivies (citations et adresses dans ordres/BRANCHEMENT.md, « Conformité des résultats », lues le 13/10/2026) :
//   - Google Maps Platform, conditions 3.2.3(b) : « Customer will not cache Google Maps Content except as expressly permitted under the Maps Service
//     Specific Terms » ; seuls l'identifiant de lieu (« You can therefore store place ID values indefinitely ») et, 30 jours, latitude et longitude
//     sont permis : aucune durée de cache n'existe pour la note, le nombre d'avis ou le nom d'un commerce.
//   - API Google Business Profile : contenu conservé « for no more than 30 calendar days » et « It cannot be manipulated or aggregated in any way ».
//     L'historique mois par mois est donc RECALCULÉ à chaque lecture à partir des avis présents sur la fiche (createTime, starRating), jamais gardé.
// Limite à dire à l'écran : un avis supprimé de la fiche n'existe plus pour l'API, il disparaît aussi des mois passés.

const ETOILES = { ONE: 1, TWO: 2, THREE: 3, FOUR: 4, FIVE: 5 };
const PARIS = new Intl.DateTimeFormat("en-CA", { timeZone: "Europe/Paris", year: "numeric", month: "2-digit", day: "2-digit" });
function partiesParis(t) { const p = Object.fromEntries(PARIS.formatToParts(new Date(t)).map(x => [x.type, x.value])); return p; }
// « AAAA-MM-01 » du mois (heure de Paris) d'un instant.
function moisParis(t) { const p = partiesParis(t); return p.year + "-" + p.month + "-01"; }
// « AAAA-MM-JJ » (heure de Paris) d'un instant.
function jourParis(t) { const p = partiesParis(t); return p.year + "-" + p.month + "-" + p.day; }
const arrondi1 = x => Math.round(x * 10) / 10;

// ---------------------------------------------------------------- Fiche du client : API Google Business Profile, accounts.locations.reviews.list
// pages : réponses brutes {reviews[], averageRating, totalReviewCount, nextPageToken}, dans l'ordre de la pagination.
// Complète seulement si la dernière page n'a plus de nextPageToken (sinon le plafond de pages a coupé la liste : pas d'historique).
function lireAvisFiche(pages) {
  const ps = (pages || []).filter(p => p && typeof p === "object" && !p.error);
  if (!ps.length) return null;
  const vus = new Set(), avis = [];
  for (const p of ps) for (const r of p.reviews || []) {
    const id = r.reviewId || r.name; if (!id || vus.has(id)) continue; vus.add(id);
    if (!r.createTime) continue;
    avis.push({ note: ETOILES[r.starRating] || null, cree: r.createTime });
  }
  const tete = ps.find(p => p.averageRating != null || p.totalReviewCount != null) || {};
  return { avis, note_google: tete.averageRating == null ? null : arrondi1(+tete.averageRating), nb_google: tete.totalReviewCount == null ? null : +tete.totalReviewCount,
           complet: !ps[ps.length - 1].nextPageToken };
}
// État de la fiche à la fin du mois m (avis écrits ce mois-là ou avant). Note : moyenne des étoiles, une décimale ; null sans avis noté.
function etatFin(lecture, m) {
  const l = lecture.avis.filter(a => moisParis(a.cree) <= m), notes = l.map(a => a.note).filter(n => n != null);
  return { note: notes.length ? arrondi1(notes.reduce((s, n) => s + n, 0) / notes.length) : null, nb_avis: l.length };
}
function etatDebut(lecture, m) {
  const l = lecture.avis.filter(a => moisParis(a.cree) < m), notes = l.map(a => a.note).filter(n => n != null);
  return { note: notes.length ? arrondi1(notes.reduce((s, n) => s + n, 0) / notes.length) : null, nb_avis: l.length };
}
// Note et nombre d'avis par mois. Mois en cours : valeurs officielles de Google (averageRating, totalReviewCount) si elles sont rendues.
// Mois passés : recalculés depuis les avis présents aujourd'hui, seulement si la liste est complète (sinon null : rien d'inventé).
function historique(lecture, listeMois, moisCourant) {
  return listeMois.map(m => {
    if (!lecture) return { mois: m, note: null, nb_avis: null };
    if (m === moisCourant && (lecture.note_google != null || lecture.nb_google != null)) {
      const e = lecture.complet ? etatFin(lecture, m) : { note: null, nb_avis: null };
      return { mois: m, note: lecture.note_google != null ? lecture.note_google : e.note, nb_avis: lecture.nb_google != null ? lecture.nb_google : e.nb_avis };
    }
    if (!lecture.complet) return { mois: m, note: null, nb_avis: null };
    return Object.assign({ mois: m }, etatFin(lecture, m));
  });
}
function avisDuMois(lecture, m) { return lecture && lecture.complet ? lecture.avis.filter(a => moisParis(a.cree) === m).length : null; }
// Bilan d'un mois écoulé : note au début et à la fin du mois, avis écrits dans le mois. null si la lecture manque ou est incomplète.
function bilanGoogle(lecture, m) {
  if (!lecture || !lecture.complet) return null;
  return { note_debut: etatDebut(lecture, m).note, note_fin: etatFin(lecture, m).note, avis_obtenus: avisDuMois(lecture, m), avis_obtenus_source: "google" };
}
// Pages de plusieurs fiches mélangées (bilan : une pagination par commerce) : regroupées par fiche grâce au nom de chaque avis
// (« accounts/…/locations/<n>/reviews/… »). Une page sans avis ne peut pas être attribuée : la fiche sans page attribuée reste non lue.
function pagesParFiche(pages) {
  const out = {};
  for (const p of pages || []) {
    const r = ((p && p.reviews) || [])[0], m = r && /(?:^|\/)(locations\/[^/]+)\/reviews\//.exec(r.name || "");
    if (m) (out[m[1]] = out[m[1]] || []).push(p);
  }
  return out;
}

// ---------------------------------------------------------------- Performances de la fiche (bilan mensuel) : API Business Profile Performance
// Méthode FetchMultiDailyMetricsTimeSeries, GET https://businessprofileperformance.googleapis.com/v1/locations/{n}:fetchMultiDailyMetricsTimeSeries, champs
// location, daily_metrics[], daily_range (start_date, end_date inclus) ; réponse multi_daily_metric_time_series[].daily_metric_time_series[].time_series.dated_values[]
// {date, value} ; « value » absent quand la valeur est zéro. Source : developers.google.com/my-business/reference/performance/rpc/google.mybusiness.performance.v1
// (« Last updated 2026-10-05 UTC », lue le 16/10/2026). Métriques (DailyMetric, même date de mise à jour) : CALL_CLICKS « The number of times the business
// profile call button was clicked. » ; BUSINESS_DIRECTION_REQUESTS ; WEBSITE_CLICKS ; BUSINESS_BOOKINGS (réservations faites via Reserve with Google).
// NON CONFIRMÉ (ordres/BRANCHEMENT.md) : la syntaxe REST des paramètres (dailyMetrics répété, dailyRange.startDate.year...) et le nom JSON « dailyMetric »
// de chaque série. Sans réponse lisible : null, et le bilan n'affiche rien de ces chiffres. Rien n'est écrit dans la base.
const METRIQUES_PERF = { CALL_CLICKS: "appels", BUSINESS_DIRECTION_REQUESTS: "itineraires", WEBSITE_CLICKS: "clics_site", BUSINESS_BOOKINGS: "reservations" };
function requetePerformance(locationId, m) {
  if (!/^locations\/[0-9]+$/.test(locationId || "") || !/^\d{4}-\d{2}-01$/.test(m || "")) return null;
  const [a, mo] = m.split("-").map(Number), fin = new Date(Date.UTC(a, mo, 0)).getUTCDate();
  const q = Object.keys(METRIQUES_PERF).map(x => "dailyMetrics=" + x)
    .concat(["dailyRange.startDate.year=" + a, "dailyRange.startDate.month=" + mo, "dailyRange.startDate.day=1", "dailyRange.endDate.year=" + a, "dailyRange.endDate.month=" + mo, "dailyRange.endDate.day=" + fin]);
  return "https://businessprofileperformance.googleapis.com/v1/" + locationId + ":fetchMultiDailyMetricsTimeSeries?" + q.join("&");
}
function performanceDuMois(rep) {
  const series = [].concat(...((rep && rep.multiDailyMetricTimeSeries) || []).map(x => (x && x.dailyMetricTimeSeries) || []));
  const out = {}; let lues = 0;
  for (const s of series) {
    const cle = METRIQUES_PERF[s && s.dailyMetric]; if (!cle) continue;
    const vals = (((s.timeSeries || {}).datedValues) || []).map(d => d && d.value != null ? Number(d.value) : 0);
    if (vals.some(v => !Number.isFinite(v) || v < 0)) continue;
    out[cle] = (out[cle] || 0) + vals.reduce((x, y) => x + y, 0); lues++;
  }
  return lues ? out : null;
}

// ---------------------------------------------------------------- Concurrents : API Places (New), détail avec le masque MASQUE_CONCURRENT
const PLACES = "https://places.googleapis.com/v1/places/";
const MASQUE_CONCURRENT = "displayName,rating,userRatingCount";   // ligne « Place Details Enterprise » (rating et userRatingCount)
function urlPlace(placeId) { if (!/^[A-Za-z0-9_-]+$/.test(String(placeId || ""))) throw new Error("identifiant de lieu invalide"); return PLACES + placeId + "?languageCode=fr&regionCode=FR"; }
function concurrentActuel(p) {
  if (!p || p.error) return null;
  return { nom: (p.displayName && p.displayName.text) || null, note: p.rating == null ? null : +p.rating, nb_avis: p.userRatingCount == null ? null : +p.userRatingCount };
}

// ---------------------------------------------------------------- Score de la fiche du client : 5 piliers sur 20, MÊME calcul que moteur/audit/piliers.py
// (seules les notes, sans les constats). Entrée : détail Places brut avec le masque MASQUE_CLIENT (= places_api.MASQUE_DETAIL, égalité testée).
const ATTRIBUTS = ["allowsDogs", "curbsidePickup", "delivery", "dineIn", "goodForChildren", "goodForGroups", "goodForWatchingSports", "liveMusic",
  "menuForChildren", "outdoorSeating", "reservable", "restroom", "servesBeer", "servesBreakfast", "servesBrunch", "servesCocktails",
  "servesCoffee", "servesDessert", "servesDinner", "servesLunch", "servesVegetarianFood", "servesWine", "takeout"];
const GROUPES = ["paymentOptions", "parkingOptions", "accessibilityOptions"];
const MASQUE_CLIENT = ["id", "displayName", "formattedAddress", "location", "types", "primaryType", "primaryTypeDisplayName", "businessStatus", "googleMapsUri",
  "photos", "rating", "userRatingCount", "regularOpeningHours", "nationalPhoneNumber", "websiteUri", "editorialSummary", "reviews"].concat(ATTRIBUTS, GROUPES).join(",");
const GENERIQUES = ["point_of_interest", "establishment"], VAGUES = GENERIQUES.concat(["store", "food"]), SEUIL_HD = 1200;
const NOMS_PILIERS = { profil: "Complétude du profil", categories: "Catégories et attributs", photos: "Photos", avis: "Avis", engagement: "Signaux d'engagement" };
function norm(s) { return String(s || "").toLowerCase().normalize("NFD").replace(/\p{Mn}/gu, "").replace(/[^a-z0-9]+/g, " ").trim(); }
const palier = (v, paliers, defaut = 0) => { for (const [seuil, pts] of paliers) if (v >= seuil) return pts; return defaut; };
const verdict = n => n >= 16 ? "Solide" : n >= 10 ? "À renforcer" : "Prioritaire";
const jours = (a, b) => Math.round((Date.UTC(+a.slice(0, 4), +a.slice(5, 7) - 1, +a.slice(8, 10)) - Date.UTC(+b.slice(0, 4), +b.slice(5, 7) - 1, +b.slice(8, 10))) / 86400000);
function scoreFiche(p, dateRef) {
  if (!p || p.error || !p.id) return null;
  const nom = (p.displayName && p.displayName.text) || null, horaires = (p.regularOpeningHours || {}).weekdayDescriptions || [];
  const t = p.primaryType || null, types = p.types || [];
  const nbAtt = ATTRIBUTS.filter(a => typeof p[a] === "boolean").length + GROUPES.filter(g => p[g] && typeof p[g] === "object" && !Array.isArray(p[g]) && Object.keys(p[g]).length).length;
  const photos = (p.photos || []).map(x => ({ l: x.widthPx || 0, h: x.heightPx || 0, auteurs: (x.authorAttributions || []).filter(a => a.displayName).map(a => a.displayName) }));
  const avis = (p.reviews || []).map(a => { const tx = ((a.originalText || a.text || {}).text || "").trim(); return { note: a.rating == null ? null : a.rating, texte: !!tx, date: (a.publishTime || "").slice(0, 10) || null }; });
  const nbH = horaires.length, n = photos.length;
  const profil = (p.formattedAddress ? 3 : 0) + (p.nationalPhoneNumber ? 4 : 0) + (p.websiteUri ? 4 : 0) + (nbH >= 7 ? 4 : nbH ? 2 : 0)
    + (p.businessStatus === "OPERATIONAL" ? 2 : 0) + (p.editorialSummary && p.editorialSummary.text ? 2 : 0) + (t ? 1 : 0);
  const sec = types.filter(x => x !== t && !VAGUES.includes(x)).length;   // secondaires pertinentes : 4 pour 1 à 3, sinon 2 avec une catégorie principale (piliers.py, 21/10/2026)
  const categories = (t ? 6 : 0) + (t && !VAGUES.includes(t) ? 3 : 0) + (sec >= 1 && sec <= 3 ? 4 : t ? 2 : 0) + palier(nbAtt, [[6, 7], [3, 4], [1, 2]]);
  const duCommerce = nom ? photos.filter(x => x.auteurs.some(a => norm(a) === norm(nom))).length : 0;
  const hd = photos.filter(x => Math.max(x.l, x.h) >= SEUIL_HD).length;
  const ph = Math.min(n, 10) + (duCommerce >= 3 ? 4 : duCommerce ? 2 : 0) + (n ? (hd === n ? 4 : hd * 2 >= n ? 2 : 0) : 0) + (photos.some(x => x.l > x.h) ? 2 : 0);
  const rediges = avis.filter(a => a.texte).length, bas = avis.filter(a => a.note != null && a.note <= 2).length, note = p.rating == null ? null : +p.rating;
  const av = (note == null ? 0 : palier(note, [[4.5, 8], [4.2, 6], [4.0, 5], [3.5, 3]], 1)) + palier(+p.userRatingCount || 0, [[200, 7], [100, 6], [50, 5], [20, 3], [5, 2], [1, 1]])
    + (rediges >= 4 ? 3 : rediges >= 2 ? 2 : rediges) + (avis.length ? (bas === 0 ? 2 : bas === 1 ? 1 : 0) : 0);
  const dates = avis.map(a => a.date).filter(Boolean).sort(), age = dates.length ? jours(dateRef, dates[dates.length - 1]) : null;
  const recents = dates.filter(d => jours(dateRef, d) <= 365).length;
  const eng = (age == null ? 0 : age <= 30 ? 10 : age <= 90 ? 8 : age <= 180 ? 5 : age <= 365 ? 2 : 0) + ({ 0: 0, 1: 1, 2: 3, 3: 4 }[recents] ?? 6)
    + (p.websiteUri ? 2 : 0) + (p.nationalPhoneNumber ? 2 : 0);
  const notes = { profil, categories, photos: ph, avis: av, engagement: eng };
  const piliers = Object.keys(NOMS_PILIERS).map(cle => ({ cle, nom: NOMS_PILIERS[cle], note: notes[cle], sur: 20, verdict: verdict(notes[cle]) }));
  return { score: piliers.reduce((s, x) => s + x.note, 0), piliers };
}

// ---------------------------------------------------------------- Réponse à l'espace : résultats de la base (fonction resultats) + lecture du jour
// R : réponse de resultats() (note, nb_avis, audit, concurrents et nouveaux_avis vides : rien n'est gardé).
// lecture : {statut: "ok" | "limite" | "erreur", maintenant (ISO), pages (avis de la fiche, null si fiche non reliée), client (détail Places ou null),
//            concurrents: [{nom, place}] dans l'ordre de R.concurrents}.
// Rend R au format du contrat, complété, plus « lecture_google » (ce qui a été lu, quand, et ce qui manque). Ne touche pas aux chiffres de RENOM.
function fusionner(R, lecture) {
  const out = JSON.parse(JSON.stringify(R || {})), l = lecture || { statut: "erreur" }, maintenant = l.maintenant || new Date().toISOString();
  const m1 = moisParis(maintenant), mois = out.mois || [];
  const info = { le: maintenant, statut: l.statut || "erreur", fiche: "non_lue", concurrents: "non_lus", score: "non_calcule", historique_reconstitue: false };
  if (info.statut === "ok") {
    const fiche = l.pages ? lireAvisFiche(l.pages) : null;
    info.fiche = l.pages == null ? "non_reliee" : !fiche ? "erreur" : fiche.complet ? "lue" : "incomplete";
    if (fiche) {
      const h = historique(fiche, mois.map(x => x.mois), m1);
      mois.forEach((x, i) => { x.note = h[i].note; x.nb_avis = h[i].nb_avis; });
      info.historique_reconstitue = fiche.complet && mois.length > 1;
      if (out.collecte) out.collecte.nouveaux_avis = avisDuMois(fiche, m1);
    }
    const lus = (l.concurrents || []).map(k => concurrentActuel(k.place));
    (out.concurrents || []).forEach((k, i) => {
      const c = lus[i]; if (!c) return;
      if (c.nom) k.nom = c.nom;
      k.mois = [{ mois: m1, note: c.note, nb_avis: c.nb_avis }];
    });
    info.concurrents = !(out.concurrents || []).length ? "aucun" : lus.filter(Boolean).length === out.concurrents.length ? "lus" : lus.some(Boolean) ? "en_partie" : "erreur";
    const s = l.client == null ? null : scoreFiche(l.client, jourParis(maintenant));
    if (s) { out.audit = [{ mois: m1, score: s.score, piliers: s.piliers }]; info.score = "calcule"; }
    else info.score = l.client == null ? "non_reliee" : "erreur";
  }
  out.lecture_google = info;
  return out;
}

// Une seule ligne d'export : elle est retirée quand le module est recopié dans un nœud Code (n8n/build_maj_membre.py, module()).
// Thèmes des avis CALCULÉS À LA DEMANDE (écran Résultats, n8n/renom-resultats-google.json), jamais conservés.
// Règle des API Business Profile, « Content storage » (developers.google.com/my-business/content/policies, relue le 13/10/2026) : contenu gardé
// « for no more than 30 calendar days » et « It cannot be manipulated or aggregated in any way ». Les avis analysés sont ceux que RENOM garde
// encore (30 jours au plus, non sensibles, non effacés) ; le résultat va dans la réponse à l'espace et nulle part ailleurs.
// Afficher ces comptes reste une agrégation affichée : point à faire valider (ordres/BRANCHEMENT.md).
// Mêmes contrôles que claude_api.themes_avis (Python, audit) : extrait recopié mot pour mot, thème porté par deux avis au moins, cinq thèmes au plus.
const plat = s => String(s || "").replace(/\s+/g, " ").trim();
const AVIS_MAX = 50;   // choix RENOM

// Corps de la requête à Claude, ou null s'il n'y a pas deux avis rédigés (rien n'est inventé). thinking « between_tools » : réflexion coupée
// (Sonnet 5.5 réfléchit par défaut et la réflexion consomme max_tokens : moteur/claude_texte.js). La réponse se lit par texteClaude, jamais content[0].
function requeteThemes(avis, consigne, modele) {
  const rediges = (avis || []).filter(a => plat(a.texte) && !a.sensible && !a.efface_le).slice(0, AVIS_MAX);
  if (rediges.length < 2) return null;
  return { model: modele || "claude-sonnet-5-5", max_tokens: 1200, thinking: { type: "between_tools" }, system: consigne,
    messages: [{ role: "user", content: JSON.stringify(rediges.map((a, i) => ({ avis: i + 1, note: a.note, texte: a.texte }))) }] };
}
// Réponse de Claude -> [{theme, positif, negatif}] (format du contrat). Illisible : [].
function lireThemes(texte, avis) {
  const rediges = (avis || []).filter(a => plat(a.texte) && !a.sensible && !a.efface_le).slice(0, AVIS_MAX);
  let j = null; try { const m = String(texte || "").match(/\{[\s\S]*\}/); j = m ? JSON.parse(m[0]) : null; } catch (e) { return []; }
  const out = {};
  for (const t of ((j && j.themes) || []).slice(0, 5)) {
    const nom = plat(t.theme);
    if (!nom || nom.length > 60 || nom.split(" ").length > 6 || /--|—|–|\d/.test(nom) || !["positif", "negatif"].includes(t.sens)) continue;
    const vus = new Set();
    for (const e of t.extraits || []) { const i = e.avis, x = plat(e.extrait);
      if (Number.isInteger(i) && i >= 1 && i <= rediges.length && !vus.has(i) && x && x.split(" ").length <= 15 && plat(rediges[i - 1].texte).includes(x)) vus.add(i); }
    if (vus.size < 2) continue;
    const o = out[nom] || (out[nom] = { theme: nom, positif: 0, negatif: 0 }); o[t.sens] += vus.size;
  }
  return Object.values(out);
}
// Réponse de l'API Claude (POST /v1/messages) -> texte. Une seule source, collée dans les nœuds Code de n8n qui lisent Claude
// (moteur/avis/build_workflow.py, n8n/build_commentaires.py, n8n/build_maj_membre.py) ; même règle en Python : moteur/claude_api.texte.
// Pourquoi (exécution n8n 50790 du 23/10/2026) : Claude Sonnet 5.5 réfléchit par défaut quand le champ `thinking` est absent, la réflexion
// compte dans max_tokens, et content[0] est alors le bloc { type: "thinking" } : lire content[0].text donnait une réponse vide.
// Le texte est celui des blocs { type: "text" }, concaténés dans l'ordre ; aucun bloc de texte (réflexion seule, erreur, réponse absente) : "".
// REFLEXION : réglage envoyé dans CHAQUE corps de requête. Sonnet 5.5 refuse { type: "disabled" } (erreur 400) ; « between_tools » coupe la
// réflexion en amont (sans outils, la réponse ne contient que du texte), n'accepte aucun autre champ (ni budget_tokens ni display), à l'effort
// high ou en dessous (aucun effort envoyé : le défaut est high). Documentation : platform.claude.com/docs/en/build-with-claude/thinking, lue le 23/10/2026.
const REFLEXION = { type: "between_tools" };
function texteClaude(rep) {
  const blocs = rep && Array.isArray(rep.content) ? rep.content : [];
  return blocs.filter(b => b && b.type === "text" && typeof b.text === "string").map(b => b.text).join("");
}
// ---- Nœud « Rédiger le bilan » : bilan de la base (bilan_mois_de, une réponse par destinataire, dans l'ordre) complété par la lecture de la fiche
// Google faite à l'instant : note au début et à la fin du mois, avis écrits dans le mois (source « google ») ; statistiques du mois (appels, itinéraires,
// clics vers le site) et thèmes des avis quand ils sont lus. Rien n'est écrit dans la base.
const dest = $('Mois écoulé et destinataires').all(), bilans = $('Bilan du mois (Supabase)').all();
const parFiche = pagesParFiche($('Avis des fiches (Business Profile)').all().map(i => i.json));
const tous = (n) => { try { return $(n).all(); } catch (e) { return []; } };
const perfDemandes = tous('Performances à lire'), perfRep = tous('Performances (Business Profile)'), perf = {};
perfDemandes.forEach((it, i) => { if (it.json.commerce_id && perfRep[i]) perf[it.json.commerce_id] = performanceDuMois(perfRep[i].json); });
const thDemandes = tous('Thèmes à demander'), thRep = tous('Claude : thèmes du mois'), avisMois = tous('Avis du mois (Supabase)').map(i => i.json), themes = {};
thDemandes.forEach((it, i) => { if (it.json.commerce_id && thRep[i]) themes[it.json.commerce_id] = lireThemes(texteClaude(thRep[i].json), avisMois.filter(a => a.commerce_id === it.json.commerce_id)); });
return bilans.map((it, i) => { const c = dest[i].json.commerce, m = dest[i].json.mois;
  const g = bilanGoogle(c.google_location_id && parFiche[c.google_location_id] ? lireAvisFiche(parFiche[c.google_location_id]) : null, m);
  const e = bilanEmail(Object.assign({}, it.json, g || {}, {performance: perf[c.id] || null, themes: themes[c.id] || []}), c, $vars.RENOM_URL_ESPACE);
  return {json: {destinataire: c.email_validation, sujet: e.sujet, html: e.html, texte: e.texte, commerce_id: c.id, mois: m, source_avis: g ? 'google' : it.json.avis_obtenus_source,
                 performance: !!perf[c.id], themes: (themes[c.id] || []).length}}; });

