    attend: (q, n, plus) => `${q} ${plus ? "are" : "is"} awaiting your approval for ${n}. One click is enough, no password needed.`, voir: "View and approve",
    h1: (n, q) => (n === 1 ? q.replace(/^1 /, "One ") : q) + " to approve.", chapo: "Nothing is published without your approval.", apercu: (q, n) => `${q} for ${n}. One click is enough, no password needed.`,
    expire: d => `Each link can be used only once and expires on ${d}.`, aussi: l => `You can also approve everything from ${l}.`, votreEspace: "your account", espace: "Your account: ", separateur: ": ",
    transfert: "Do not forward this message: each link lets someone approve on your behalf.",
    auto1: d => `If you do not reply, this post will be published from ${d}.`, autoN: "If you do not reply, each post will be published from the date shown.",
    auto: d => `If you do not reply: published from ${d}.` },
  nl: { commentaire: "Antwoord op een reactie", avis: "Antwoord op een review", etoiles: ["ster", "sterren"], story: "Story", video: "Video", publication: "Post", avisVide: "Review zonder tekst",
    commentaireVide: "Reactie", contenus: ["post", "posts"], reponses: ["antwoord op een review", "antwoorden op reviews"], elements: ["item", "items"], sujet: (q, n) => `${q} om goed te keuren voor ${n}`,
    attend: (q, n, plus) => `${q} ${plus ? "wachten" : "wacht"} op uw goedkeuring voor ${n}. Eén klik volstaat, zonder wachtwoord.`, voir: "Bekijken en goedkeuren",
    h1: (n, q) => (n === 1 ? q.replace(/^1 /, "Eén ") : q) + " om goed te keuren.", chapo: "Niets wordt gepubliceerd zonder uw akkoord.", apercu: (q, n) => `${q} voor ${n}. Eén klik volstaat, zonder wachtwoord.`,
