    p1: (nom, r) => `Een reactie onder een post van ${nom} op ${r} werd als gevoelig ingedeeld. BoostImpact antwoordt er niet op en heeft niets voorbereid: u beslist zelf wat u ermee doet.`,
    reseau: "Netwerk", auteur: "Geplaatst door", commentaire: "Reactie", motif: "Reden", inconnu: "onbekend", bonjour: "Goeiedag,", publication: "De post openen", vos: "Uw reacties openen",
    publicationTexte: "Post: ", vosTexte: "Uw reacties: ", sep: ": ", pied: "BoostImpact, automatische melding.",
    h1: "Een reactie vraagt om uw beslissing.", chapo: r => `Als gevoelig ingedeeld op ${r}. Er werd geen antwoord voorbereid.`, apercu: r => `Een gevoelige reactie op ${r}: BoostImpact antwoordt er niet op, de beslissing ligt bij u.`,
    sansTexte: "Reactie zonder tekst", raison: n => `Automatische melding van BoostImpact voor ${n}: voor een als gevoelig ingedeelde reactie is geen antwoord voorbereid.`,
    motifs: { insulte: "belediging", accusation: "beschuldiging", "santé": "gezondheid", juridique: "juridisch", "classement incertain": "onzekere classificatie" } },
};

// Commentaire sensible : alerte au commerçant (et à PJ, adresse visible, comme pour les avis sensibles). Aucune réponse n'a été préparée.
function alerteCommentaireEmail(cm, commerce, ctx) {
  // Équipe : RENOM_EMAIL_PJ, une adresse ou plusieurs séparées par des virgules (27/10/2026 : PJ et Pascal).
  const dest = [commerce.email_validation].filter(emailValide).concat(adressesEquipe(ctx.emailPJ) ? adressesEquipe(ctx.emailPJ).split(", ") : []);
  if (!dest.length) throw new Error("aucun destinataire valide");
  const lg = langueEmail(commerce.langue), T = TEXTES_ALERTE[lg];
  const motifs = (cm.raisons || []).map(x => T.motifs[x] || x).join(", ") || T.sensible;
  const reseau = RESEAUX[cm.reseau] || cm.reseau, sujet = T.sujet(reseau, motifs);
  const p1 = T.p1(nom_(commerce.nom), reseau);
  const lignes = [[T.reseau, reseau], [T.auteur, cm.auteur || T.inconnu], [T.commentaire, String(cm.texte || "").slice(0, 500)], [T.motif, motifs]];
  // Mise en page commune (20/10/2026) : le commentaire cité d'abord, puis son contexte ; bouton principal vers la publication (sinon vers l'écran des
  // commentaires de l'espace), l'autre lien en texte. Le texte brut porte désormais le pied légal dans la langue, comme le HTML.
  const M = MISE_EN_PAGE, mots = M.MOTS[lg], vos = adresse(ctx.urlEspace, "/#/commentaires"), nom = nom_(commerce.nom);
  const html = M.courriel({ lg, titre: sujet, apercu: T.apercu(reseau), repere: nom, h1: T.h1, chapo: T.chapo(reseau),
    corps: [M.p(echapper(T.bonjour), { couleur: M.C.texte }), M.p(echapper(p1), { marge: "0 0 24px 0" }),
