    texte: ["Une réponse validée par le commerçant attend d'être publiée sous le commentaire, depuis le compte du commerce.", "", ...lignes.map(([a, b]) => `${a} : ${b}`), cm.lien ? "\nPublication : " + cm.lien : "", "", "Console : " + adresse(ctx.urlEspace, "/console.html#/apublier")].join("\n") };
}
const ctx = {urlEspace: $vars.RENOM_URL_ESPACE, emailPJ: $vars.RENOM_EMAIL_PJ};

