    expire: d => `Elke link werkt maar één keer en verloopt op ${d}.`, aussi: l => `U kunt ook alles goedkeuren vanuit ${l}.`, votreEspace: "uw klantenzone", espace: "Uw klantenzone: ", separateur: ": ",
    transfert: "Stuur dit bericht niet door: met elke link kan iemand in uw plaats goedkeuren.",
    auto1: d => `Zonder antwoord van u wordt deze post gepubliceerd vanaf ${d}.`, autoN: "Zonder antwoord van u wordt elke post gepubliceerd vanaf de vermelde datum.",
    auto: d => `Zonder antwoord van u: gepubliceerd vanaf ${d}.` },
};
function libelle(it, lg) {
  const T = TEXTES_VALIDATION[langueEmail(lg)];
  if (it.objet === "commentaire") return T.commentaire + (it.commentaire && it.commentaire.reseau ? " (" + ({ instagram: "Instagram", facebook: "Facebook" }[it.commentaire.reseau] || it.commentaire.reseau) + ")" : "");
  if (it.objet === "avis") return T.avis + (it.avis && it.avis.note ? " (" + pluriel(it.avis.note, T.etoiles[0], T.etoiles[1]) + ")" : "");
  const c = it.contenu || {};
  return c.format === "story" ? T.story : c.type === "video" ? T.video : T.publication;
}
function extrait(it, lg) {
  const T = TEXTES_VALIDATION[langueEmail(lg)];
  const t = it.objet === "avis" ? (it.avis && it.avis.texte) || T.avisVide : it.objet === "commentaire" ? (it.commentaire && it.commentaire.texte) || T.commentaireVide : (it.contenu && it.contenu.legende) || "";
  const plat = String(t).replace(/\s+/g, " ").trim();
  return plat.length > 140 ? plat.slice(0, 139).replace(/\s+\S*$/, "") + "..." : plat;
}
function notificationEmail(items, commerce, urlEspace) {
  if (!items.length) throw new Error("aucun élément à annoncer");
  const lg = langueEmail(commerce.langue), T = TEXTES_VALIDATION[lg], M = MISE_EN_PAGE, mots = M.MOTS[lg];
  const n = items.length, toutContenu = items.every(i => i.objet === "contenu"), toutAvis = items.every(i => i.objet === "avis");
  const quoi = pluriel(n, ...(toutContenu ? T.contenus : toutAvis ? T.reponses : T.elements));
  const sujet = T.sujet(quoi, commerce.nom);
  const expire = items.map(i => i.expire_le).sort()[0];
  const auto = i => i.objet === "contenu" && i.contenu && i.contenu.publication_auto_le ? dateHeure(i.contenu.publication_auto_le, lg) : null;
  const liens = items.map(i => ({ titre: libelle(i, lg), texte: extrait(i, lg), url: adresse(urlEspace, "/valider.html#" + i.jeton), auto: auto(i) }));
  const dates = liens.filter(l => l.auto);
  const chapo = dates.length ? (n === 1 ? T.auto1(dates[0].auto) : T.autoN) : commerce.delegation_offre && items.some(i => i.objet === "commentaire") ? null : T.chapo;
  // Un seul élément : son bouton est le bouton principal. Plusieurs : un bouton à contour par élément, aucun n'est plus important qu'un autre ; la date
  // de publication sans réponse (délégation) est écrite sur chaque carte.
  const html = M.courriel({ lg, titre: sujet, apercu: T.apercu(quoi, commerce.nom), repere: commerce.nom, h1: T.h1(n, quoi), chapo,
    corps: [M.p(echapper(TEXTES_BILAN[lg].bonjour), { couleur: M.C.texte }), M.p(T.attend(echapper(quoi), echapper(commerce.nom), n > 1), { marge: "0 0 24px 0" }),
      ...liens.map(l => M.carte(l.titre, l.texte, (n > 1 && l.auto ? M.p(echapper(T.auto(l.auto)), { marge: "0 0 4px 0", taille: 14, couleur: M.C.texteDiscret }) : "")
        + M.bouton(l.url, T.voir, { secondaire: n > 1, marge: n > 1 ? "6px 0 0 0" : "10px 0 0 0" }))),
      M.espace(12),
      M.p(`${T.expire(echapper(dateLettres(expire, lg)))} ${T.aussi(M.lienTexte(adresse(urlEspace), T.votreEspace, M.C.texteDiscret))}`, { marge: "0 0 8px 0", taille: 14, couleur: M.C.texteDiscret }),
      M.p(echapper(T.transfert), { marge: "0 0 8px 0", taille: 14, couleur: M.C.texteDiscret })],
    pied: [mots.client(commerce.nom), mots.stop] });
  const texte = [TEXTES_BILAN[lg].bonjour, ``, T.attend(quoi, commerce.nom, n > 1), ...(chapo && chapo !== T.chapo ? [chapo] : []), ``,
    ...liens.flatMap(l => [`${l.titre}${T.separateur}${l.texte}`, ...(n > 1 && l.auto ? [T.auto(l.auto)] : []), l.url, ``]),
    `${T.expire(dateLettres(expire, lg))} ${T.espace}${adresse(urlEspace)}`, T.transfert, ``,
    mots.question, mots.equipe, ``, mots.client(commerce.nom), mots.stop].join("\n");
  return { sujet, html, texte: avecPied(texte, lg) };
}

// Une seule ligne d'export : la copie dans n8n (n8n/build_*.py) retire les lignes qui commencent par « module.exports ».
// Emails des réponses aux commentaires (n8n/build_commentaires.py les recopie après moteur/courriels/courriels.js ; la ligne require est retirée).
// NOUVEAUX gabarits (13/10/2026) : pied minimal (« BoostImpact, alerte automatique. »), à compléter par les mentions légales communes aux emails.
// 20/10/2026 : l'alerte au commerçant passe à la mise en page commune (MISE_EN_PAGE de courriels.js) ; l'email à PJ garde page().
// Langues (17/10/2026) : l'alerte au commerçant suit la langue du commerce (commerce.langue : fr, en, nl) ; l'email à PJ reste en français.
const RESEAUX = { instagram: "Instagram", facebook: "Facebook" };
const nom_ = s => String(s == null ? "" : s).replace(/["<>\r\n]/g, "").trim();
const emailValide = e => /^[^\s@<>"]+@[^\s@<>"]+\.[^\s@<>"]{2,}$/.test(e || "");

// Motifs (moteur/commentaires/regles.js, SENSIBLE et SENSIBLE_NL ; consigne moteur/consignes/commentaires.md) dans la langue du commerce ; un motif
// inconnu est écrit tel quel.
const TEXTES_ALERTE = {
  fr: { sujet: (r, m) => `Commentaire à traiter vous-même sur ${r} (${m})`, sensible: "sensible",
    p1: (nom, r) => `Un commentaire laissé sous une publication de ${nom} sur ${r} a été classé sensible. BoostImpact n'y répond pas et n'a rien préparé : c'est à vous de décider quoi faire.`,
    reseau: "Réseau", auteur: "Auteur", commentaire: "Commentaire", motif: "Motif", inconnu: "inconnu", bonjour: "Bonjour,", publication: "Ouvrir la publication", vos: "Ouvrir vos commentaires",
    publicationTexte: "Publication : ", vosTexte: "Vos commentaires : ", sep: " : ", pied: "BoostImpact, alerte automatique.", motifs: {},
    h1: "Un commentaire demande votre décision.", chapo: r => `Classé sensible sur ${r}. Aucune réponse n'a été préparée.`, apercu: r => `Un commentaire sensible sur ${r} : BoostImpact n'y répond pas, la décision vous revient.`,
    sansTexte: "Commentaire sans texte", raison: n => `Alerte automatique de BoostImpact pour ${n} : un commentaire classé sensible n'a aucune réponse préparée.` },
  en: { sujet: (r, m) => `Comment to handle yourself on ${r} (${m})`, sensible: "sensitive",
    p1: (nom, r) => `A comment left under a post by ${nom} on ${r} has been classified as sensitive. BoostImpact does not reply to it and has prepared nothing: it is up to you to decide what to do.`,
    reseau: "Network", auteur: "Author", commentaire: "Comment", motif: "Reason", inconnu: "unknown", bonjour: "Hello,", publication: "Open the post", vos: "Open your comments",
    publicationTexte: "Post: ", vosTexte: "Your comments: ", sep: ": ", pied: "BoostImpact, automatic alert.",
    h1: "A comment needs your decision.", chapo: r => `Classified as sensitive on ${r}. No reply has been prepared.`, apercu: r => `A sensitive comment on ${r}: BoostImpact does not reply to it, the decision is yours.`,
    sansTexte: "Comment without text", raison: n => `Automatic alert from BoostImpact for ${n}: a comment classified as sensitive has no prepared reply.`,
    motifs: { insulte: "insult", accusation: "accusation", "santé": "health", juridique: "legal", "classement incertain": "uncertain classification" } },
  nl: { sujet: (r, m) => `Reactie die u zelf moet behandelen op ${r} (${m})`, sensible: "gevoelig",
    p1: (nom, r) => `Een reactie onder een post van ${nom} op ${r} werd als gevoelig ingedeeld. BoostImpact antwoordt er niet op en heeft niets voorbereid: u beslist zelf wat u ermee doet.`,
    reseau: "Netwerk", auteur: "Geplaatst door", commentaire: "Reactie", motif: "Reden", inconnu: "onbekend", bonjour: "Goeiedag,", publication: "De post openen", vos: "Uw reacties openen",
    publicationTexte: "Post: ", vosTexte: "Uw reacties: ", sep: ": ", pied: "BoostImpact, automatische melding.",
    h1: "Een reactie vraagt om uw beslissing.", chapo: r => `Als gevoelig ingedeeld op ${r}. Er werd geen antwoord voorbereid.`, apercu: r => `Een gevoelige reactie op ${r}: BoostImpact antwoordt er niet op, de beslissing ligt bij u.`,
    sansTexte: "Reactie zonder tekst", raison: n => `Automatische melding van BoostImpact voor ${n}: voor een als gevoelig ingedeelde reactie is geen antwoord voorbereid.`,
    motifs: { insulte: "belediging", accusation: "beschuldiging", "santé": "gezondheid", juridique: "juridisch", "classement incertain": "onzekere classificatie" } },
};

// Commentaire sensible : alerte au commerçant (et à PJ, adresse visible, comme pour les avis sensibles). Aucune réponse n'a été préparée.
function alerteCommentaireEmail(cm, commerce, ctx) {
  // Équipe : RENOM_EMAIL_PJ, une adresse ou plusieurs séparées par des virgules (27/10/2026 : PJ et Pascal).
  const dest = [commerce.email_validation].filter(emailValide).concat(adressesEquipe(ctx.emailPJ) ? adressesEquipe(ctx.emailPJ).split(", ") : []);
  if (!dest.length) throw new Error("aucun destinataire valide");
  const lg = langueEmail(commerce.langue), T = TEXTES_ALERTE[lg];
  const motifs = (cm.raisons || []).map(x => T.motifs[x] || x).join(", ") || T.sensible;
  const reseau = RESEAUX[cm.reseau] || cm.reseau, sujet = T.sujet(reseau, motifs);
  const p1 = T.p1(nom_(commerce.nom), reseau);
  const lignes = [[T.reseau, reseau], [T.auteur, cm.auteur || T.inconnu], [T.commentaire, String(cm.texte || "").slice(0, 500)], [T.motif, motifs]];
  // Mise en page commune (20/10/2026) : le commentaire cité d'abord, puis son contexte ; bouton principal vers la publication (sinon vers l'écran des
  // commentaires de l'espace), l'autre lien en texte. Le texte brut porte désormais le pied légal dans la langue, comme le HTML.
  const M = MISE_EN_PAGE, mots = M.MOTS[lg], vos = adresse(ctx.urlEspace, "/#/commentaires"), nom = nom_(commerce.nom);
  const html = M.courriel({ lg, titre: sujet, apercu: T.apercu(reseau), repere: nom, h1: T.h1, chapo: T.chapo(reseau),
    corps: [M.p(echapper(T.bonjour), { couleur: M.C.texte }), M.p(echapper(p1), { marge: "0 0 24px 0" }),
      M.carte((cm.auteur || T.inconnu) + T.sep.trimEnd(), String(cm.texte || "").slice(0, 500) || T.sansTexte),
      M.lignes([[T.reseau, reseau], [T.motif, motifs.charAt(0).toUpperCase() + motifs.slice(1)]]),
      cm.lien ? M.bouton(cm.lien, T.publication, { marge: "8px 0 18px 0" }) + M.p(M.lienTexte(vos, T.vos), { taille: 15 }) : M.bouton(vos, T.vos)],
    pied: [T.raison(nom)] });
