}
function extrait(it, lg) {
  const T = TEXTES_VALIDATION[langueEmail(lg)];
  const t = it.objet === "avis" ? (it.avis && it.avis.texte) || T.avisVide : it.objet === "commentaire" ? (it.commentaire && it.commentaire.texte) || T.commentaireVide : (it.contenu && it.contenu.legende) || "";
