  const n = +el.numero, nom = nettoyerNom(el.commerce) || P.commerce, sig = nettoyerNom(ctx.signature) || "BoostImpact", stop = lienDesinscription(ctx.urlEspace, el.jeton_envoi);
  if (![1, 2, 3].includes(n)) throw new Error("numéro de relance inconnu");
  const quand = el.audit_le ? P.quand(dateLettres(el.audit_le, lg)) : P.recemment;
