// Étapes de la mise en route, numérotées dans l'ordre de l'espace (1 à 4, ou 1 à 3 sans réseaux) : [{numero, titre, aide}].
const etapesNumerotees = (cles, P, ordre = ORDRE_POINTS) => cles.map(k => ({ numero: String(ordre.indexOf(k) + 1), titre: P[k].titre, aide: P[k].aide }));
