// (n8n ne lit pas le dépôt), comparée par moteur/tests/test_service.js. PUBLICATIONS_GOOGLE : publications par mois de l'Essentiel (offres.json).
const OFFRES_SANS_RESEAUX = ["essentiel"], PUBLICATIONS_GOOGLE = { essentiel: 2 };
const avecReseaux = offre => !OFFRES_SANS_RESEAUX.includes(offre);
// Prix des offres (27/10/2026, email « plafond atteint » et bouton « Passer à <offre> » de l'espace) : prix_ht (par mois en paiement annuel) et
// prix_mensuel_ht (au mois, sans engagement) de moteur/offres.json, recopiés ici (n8n ne lit pas le dépôt), comparés par moteur/tests/test_service.js.
const PRIX_OFFRES = { essentiel: { annuel: 79, mensuel: 95 }, standard: { annuel: 190, mensuel: 228 }, premium: { annuel: 390, mensuel: 468 } };
const pointsOffre = offre => ORDRE_POINTS.filter(k => k !== "metricool" || avecReseaux(offre));
// Nombre d'étapes en toutes lettres (titres et phrases) ; au-delà, le chiffre.
const NOMBRES = { fr: { 3: "trois", 4: "quatre" }, en: { 3: "three", 4: "four" }, nl: { 3: "drie", 4: "vier" } };
const enLettres = (n, lg) => (NOMBRES[lg] || NOMBRES.fr)[n] || String(n);
const capitale = x => x.charAt(0).toUpperCase() + x.slice(1);
const nettoyerNom = s => String(s == null ? "" : s).replace(/["<>\r\n]/g, "").trim();
const bouton = (href, texte) => `<tr><td style="padding:0 0 16px 0"><a href="${echapper(href)}" style="display:inline-block;background:${ENCRE};color:#F6F4EF;text-decoration:none;font-weight:600;padding:12px 22px;border-radius:6px">${echapper(texte)}</a></td></tr>`;
const discret = html => para(html, `color:${GRIS};font-size:14px`);
const liste = items => `<tr><td style="padding:0 0 16px 0"><table role="presentation" width="100%" cellspacing="0" cellpadding="0">${items.map(([t, s]) =>
  `<tr><td style="padding:10px 0;border-bottom:1px solid ${FILET}"><strong>${echapper(t)}</strong>${s ? `<br><span style="color:${GRIS}">${echapper(s)}</span>` : ""}</td></tr>`).join("")}</table></td></tr>`;
function httpsOuRien(u) { const x = String(u || "").trim(); return /^https:\/\/[^\s"<>]+$/.test(x) ? x : null; }

// Mots communs aux emails du commerçant. Noms des offres : moteur/offres.json (« nom », « nom_en », « nom_nl »), seule source,
// recopiés ici (n8n ne lit pas le dépôt) et comparés par moteur/tests/test_courriels_langues.js. Le nom français est aussi recopié (25/10/2026 :
// « Standard » devient « Croissance ») : l'email affiche le nom du dépôt même si la base garde encore l'ancien nom (offres.nom).
const COMMUN = {
  fr: { bonjour: "Bonjour,", ouvrir: "Ouvrir mon espace", espace: "Votre espace : ", sep: " : ", desinscrire: "se désinscrire" },
  en: { bonjour: "Hello,", ouvrir: "Open my account", espace: "Your account: ", sep: ": ", desinscrire: "unsubscribe" },
  nl: { bonjour: "Goeiedag,", ouvrir: "Mijn klantenzone openen", espace: "Uw klantenzone: ", sep: ": ", desinscrire: "uitschrijven" },
};
const NOMS_OFFRES = { fr: { essentiel: "Essentiel", standard: "Croissance", premium: "Premium" }, en: { essentiel: "Essential", standard: "Growth", premium: "Premium" }, nl: { essentiel: "Essentieel", standard: "Groei", premium: "Premium" } };
const nomOffre = (id, lg, nomFr) => (NOMS_OFFRES[langueEmail(lg)] || {})[id] || nomFr;

// ---- Liens publics (même règle que l'espace : adresse https, sans barre finale)
const lienAvisEmail = (url, jetonAvis, jetonEnvoi) => adresse(url, "/avis.html?source=email&envoi=" + encodeURIComponent(jetonEnvoi) + "#" + jetonAvis);
const lienDesinscription = (url, jeton) => adresse(url, "/desinscription.html#" + jeton);

// ---- 1. Demande d'avis (client du commerçant) : même texte pour tous, aucun tri, aucune contrepartie
const TEXTES_DEMANDE = {
  fr: { sujetRelance: n => `Votre avis sur ${n}, notre seul rappel`, sujet: n => `Votre avis sur ${n}`, bonjour: p => `Bonjour${p ? " " + p : ""},`,
    relance: n => `Il y a quelques jours, ${n} vous a demandé votre avis sur votre visite. Si vous avez un moment, il reste le bienvenu. C'est notre seul rappel.`,
    demande: n => `Merci de votre visite chez ${n}. Votre avis, quel qu'il soit, nous aide à nous améliorer et aide d'autres personnes à nous trouver.`,
    pied: n => `Cet email vous est envoyé par BoostImpact pour le compte de ${n}, parce que vous lui avez donné votre accord pour être contacté après votre visite. Ne plus recevoir de demande de ${n} : `,
    bouton: "Donner mon avis", merci: "Merci d'avance," },
  en: { sujetRelance: n => `Your opinion of ${n}, our only reminder`, sujet: n => `Your opinion of ${n}`, bonjour: p => `Hello${p ? " " + p : ""},`,
    relance: n => `A few days ago, ${n} asked for your opinion of your visit. If you have a moment, it is still welcome. This is our only reminder.`,
    demande: n => `Thank you for visiting ${n}. Your opinion, whatever it is, helps us improve and helps other people find us.`,
    pied: n => `This email is sent to you by BoostImpact on behalf of ${n}, because you agreed to be contacted after your visit. Stop receiving requests from ${n}: `,
    bouton: "Give my opinion", merci: "Thank you in advance," },
  nl: { sujetRelance: n => `Uw mening over ${n}, onze enige herinnering`, sujet: n => `Uw mening over ${n}`, bonjour: p => p ? `Dag ${p},` : "Goeiedag,",
    relance: n => `Enkele dagen geleden vroeg ${n} naar uw mening over uw bezoek. Als u even tijd hebt, is ze nog altijd welkom. Dit is onze enige herinnering.`,
    demande: n => `Bedankt voor uw bezoek aan ${n}. Uw mening, wat ze ook is, helpt ons om beter te worden en helpt anderen om ons te vinden.`,
    pied: n => `Deze e-mail wordt u door BoostImpact gestuurd namens ${n}, omdat u ermee hebt ingestemd na uw bezoek gecontacteerd te worden. Geen verzoeken meer ontvangen van ${n}: `,
    bouton: "Mijn mening geven", merci: "Alvast bedankt," },
};
function demandeAvisEmail(el, ctx) {
  const lg = langueEmail(el.langue), T = TEXTES_DEMANDE[lg], C = COMMUN[lg];
  const nom = nettoyerNom(el.commerce), prenom = nettoyerNom(el.prenom), relance = el.categorie === "relance_avis";
  if (!/^[0-9a-f]{32}$/.test(el.jeton_avis || "") || !/^[0-9a-f]{32}$/.test(el.jeton_envoi || "")) throw new Error("jeton de page ou d'envoi absent");
  const avisUrl = lienAvisEmail(ctx.urlEspace, el.jeton_avis, el.jeton_envoi), stop = lienDesinscription(ctx.urlEspace, el.jeton_envoi);
  const sujet = relance ? T.sujetRelance(nom) : T.sujet(nom);
  const p1 = relance ? T.relance(nom) : T.demande(nom);
  const pied = T.pied(nom);
  const html = page(sujet, [para(T.bonjour(prenom ? echapper(prenom) : "")), para(echapper(p1)), bouton(avisUrl, T.bouton), para(`${T.merci}<br>${echapper(nom)}`)],
    `${echapper(pied)}${lien(stop, C.desinscrire)}.`, lg);
  const texte = [T.bonjour(prenom), "", p1, "", T.bouton + C.sep + avisUrl, "", T.merci, nom, "", pied + stop].join("\n");
  return { destinataire: el.destinataire, expediteur_nom: `${nom} via BoostImpact`, sujet, html, texte: avecPied(texte, lg), desinscription: stop };
}

