// 27/10/2026 (audit du parcours, constats 16 et 17) : la bienvenue part 3 secondes après l'invitation de Supabase (même workflow) ; elle dit
// précisément quel email ouvrir et sur quel bouton cliquer (titres d'espace/supabase/emails/invitation.html, désormais dans la langue du commerce
// dès la première invitation), et quoi faire si le lien a expiré (page de connexion, i18n.js acc.oubli). Clés regle1 et regle2 (trois offres dans
// la même phrase) gardées pour mémoire, plus affichées.
// commerce : { nom, email, langue, offre_id, origine }. offre_id : offre du commerce (absente : avec réseaux, 4 étapes, comme avant le 26/10/2026).
// origine « paiement_en_ligne » (journal COMMERCE_CREE écrit par client_en_ligne) : objet « Bienvenue chez BoostImpact : vos N étapes… ».
function bienvenueEmail(commerce, ctx) {
  const lg = langueEmail(commerce.langue), T = TEXTES_ACCUEIL[lg], C = COMMUN[lg], P = POINTS_LANGUES[lg], M = MISE_EN_PAGE, mots = M.MOTS[lg];
  const nom = nettoyerNom(commerce.nom), url = adresse(ctx.urlEspace);
  // Sans nom, l'email partait « Bienvenue chez BoostImpact, » (18/10/2026 : réponse de la base lue comme du texte par n8n) : refusé ici,
  // le workflow d'erreur prévient PJ au lieu d'envoyer un email à trou.
  if (!nom) throw new Error("nom du commerce absent : email de bienvenue non rédigé");
  const ordre = pointsOffre(commerce.offre_id), n = ordre.length, google = !avecReseaux(commerce.offre_id);
  const sujet = commerce.origine === "paiement_en_ligne" ? T.sujetAchat(n) : T.sujet(nom, n), etapes = etapesNumerotees(ordre, P, ordre);
  // 27/10/2026 (audit du parcours, constat 17) : seulement les règles de l'offre du client (CGV, articles 8 et 9) ; plus de phrase qui explique les trois
