// Réponse d'un prospect dont l'audit attend sa fiche (25/10/2026) : r.audit = ce que rend reponse_prospect (espace/supabase/schema.sql),
// r.lecture = lireReponseAudit (moteur/courriels/reponse_audit.js), r.relance_partie = true (GitHub Actions a pris la relance), false (appel en
// erreur), null (aucune relance demandée). Relancée : PJ est informé ; refusée ou en échec : « audit en attente : relancer avec … », avec le
// job à coller dans GitHub Actions. Sans audit en attente : l'alerte d'avant, mot pour mot.
const STATUTS_AUDIT = { ambigu: "fiche ambiguë", introuvable: "fiche introuvable" };
