    L = [`${r.expediteur} a répondu à l'email « fiche à confirmer » (${statut}). Audit en attente : relancer avec ${choix || "la fiche que le prospect désigne"}. Rien n'a été relancé : ${REFUS_AUDIT[a.refus] || a.refus}.`,
