// passe à l'heure, puis le contenu part au créneau suivant). Offre avec délégation (commerce.delegation_offre) et commentaire dans l'email : rien
// de promis (l'équipe peut répondre aux commentaires du Premium). Sinon, la phrase d'avant.
const TEXTES_VALIDATION = {
  fr: { commentaire: "Réponse à un commentaire", avis: "Réponse à un avis", etoiles: ["étoile", "étoiles"], story: "Story", video: "Vidéo", publication: "Publication", avisVide: "Avis sans texte",
    commentaireVide: "Commentaire", contenus: ["contenu", "contenus"], reponses: ["réponse d'avis", "réponses d'avis"], elements: ["élément", "éléments"], sujet: (q, n) => `${q} à valider pour ${n}`,
