function relanceProspectEmail(el, ctx) {
  const rdv = httpsOuRien(ctx.rdvUrl); if (!rdv) throw new Error("variable RENOM_RDV_URL absente ou non https");
  const lg = langueEmail(el.langue), P = TEXTES_PROSPECT[lg], C = COMMUN[lg];
  const n = +el.numero, nom = nettoyerNom(el.commerce) || P.commerce, sig = nettoyerNom(ctx.signature) || "BoostImpact", stop = lienDesinscription(ctx.urlEspace, el.jeton_envoi);
  if (![1, 2, 3].includes(n)) throw new Error("numéro de relance inconnu");
  const quand = el.audit_le ? P.quand(dateLettres(el.audit_le, lg)) : P.recemment;
  const T = P[n](nom, quand);
  // 26/10/2026 : lien de rendez-vous WhatsApp (wa.me) -> « Écrire sur WhatsApp » au lieu de « Choisir un créneau » (aucun agenda derrière ce lien).
  const wa = /^https:\/\/wa\.me\//.test(rdv);
  if (wa) T.l = T.l.map(x => x === P.creneau ? P.creneauWa : x);
  const pied = P.pied;
  const html = page(T.sujet, [para(C.bonjour), ...T.l.map(x => para(echapper(x))), bouton(rdv, wa ? P.boutonWa : P.bouton), para(echapper(sig))], `${echapper(pied)}${lien(stop, C.desinscrire)}.`, lg);
  const texte = [C.bonjour, "", ...T.l, rdv, "", sig, "", pied + stop].join("\n");
  return { destinataire: el.destinataire, sujet: T.sujet, html, texte: avecPied(texte, lg), desinscription: stop };
}

