// Réponse d'un prospect dont l'audit attend sa fiche (25/10/2026) : r.audit = ce que rend reponse_prospect (espace/supabase/schema.sql),
// r.lecture = lireReponseAudit (moteur/courriels/reponse_audit.js), r.relance_partie = true (GitHub Actions a pris la relance), false (appel en
// erreur), null (aucune relance demandée). Relancée : PJ est informé ; refusée ou en échec : « audit en attente : relancer avec … », avec le
// job à coller dans GitHub Actions. Sans audit en attente : l'alerte d'avant, mot pour mot.
const STATUTS_AUDIT = { ambigu: "fiche ambiguë", introuvable: "fiche introuvable" };
const REFUS_AUDIT = { illisible: "la réponse ne contient ni numéro de fiche ni lien Google lisible", numero_inconnu: "aucune fiche proposée ne porte ce numéro",
  limite: "3 relances déjà faites en 24 h pour ce prospect (limite)" };
function reponseAuditEmail(r, ctx) {
  const a = r.audit, l = r.lecture || {}, qui = nettoyerNom(a.commerce) || r.expediteur, statut = STATUTS_AUDIT[a.audit_statut] || a.audit_statut;
  const choix = a.lien ? `le lien ${a.lien}` : a.place_id ? `la fiche n° ${l.numero} (identifiant de lieu ${a.place_id})` : null;
  const lu = l.lien ? `lien ${l.lien}` : l.numero ? `numéro ${l.numero}` : "ni numéro ni lien";
  const job = JSON.stringify(jobRelance(a.lien || a.place_id ? a : Object.assign({}, a, { place_id: null, lien: "LIEN_DE_LA_FICHE" })));
  const manuel = `Pour relancer : GitHub Actions, workflow « Rendu RENOM », Run workflow, champ job : ${job}`;
  let sujet, L;
  if (a.relance && r.relance_partie !== false) {
    sujet = `Audit relancé automatiquement : ${qui}`;
    L = [`${r.expediteur} a répondu à l'email « fiche à confirmer » (${statut}). Audit relancé automatiquement avec ${choix}, relance ${a.relances_dans_la_fenetre} sur 3 en 24 h. Ses relances commerciales sont arrêtées.`,
      "Le rapport revient par le chemin habituel (workflow « RENOM, audit de fiche Google »). S'il n'arrive pas, voir GitHub Actions, « Rendu RENOM »."];
  } else if (a.relance) {
    sujet = `Audit en attente, relance en échec : ${qui}`;
    L = [`${r.expediteur} a répondu à l'email « fiche à confirmer » (${statut}). Audit en attente : relancer avec ${choix}. L'appel à GitHub Actions a échoué, rien n'est parti.`, manuel];
  } else {
    sujet = `Audit en attente, réponse à lire : ${qui}`;
    L = [`${r.expediteur} a répondu à l'email « fiche à confirmer » (${statut}). Audit en attente : relancer avec ${choix || "la fiche que le prospect désigne"}. Rien n'a été relancé : ${REFUS_AUDIT[a.refus] || a.refus}.`,
