  const html = page(sujet, [para(`${echapper(r.expediteur)} a répondu (objet : ${echapper(r.objet || "sans objet")}). Ses relances sont arrêtées. La réponse est dans la boîte d'envoi de BoostImpact.`)], "BoostImpact, alerte automatique.");
