function demandeAvisEmail(el, ctx) {
  const lg = langueEmail(el.langue), T = TEXTES_DEMANDE[lg], C = COMMUN[lg];
  const nom = nettoyerNom(el.commerce), prenom = nettoyerNom(el.prenom), relance = el.categorie === "relance_avis";
  if (!/^[0-9a-f]{32}$/.test(el.jeton_avis || "") || !/^[0-9a-f]{32}$/.test(el.jeton_envoi || "")) throw new Error("jeton de page ou d'envoi absent");
  const avisUrl = lienAvisEmail(ctx.urlEspace, el.jeton_avis, el.jeton_envoi), stop = lienDesinscription(ctx.urlEspace, el.jeton_envoi);
  const sujet = relance ? T.sujetRelance(nom) : T.sujet(nom);
  const p1 = relance ? T.relance(nom) : T.demande(nom);
  const pied = T.pied(nom);
  const html = page(sujet, [para(T.bonjour(prenom ? echapper(prenom) : "")), para(echapper(p1)), bouton(avisUrl, T.bouton), para(`${T.merci}<br>${echapper(nom)}`)],
    `${echapper(pied)}${lien(stop, C.desinscrire)}.`, lg);
  const texte = [T.bonjour(prenom), "", p1, "", T.bouton + C.sep + avisUrl, "", T.merci, nom, "", pied + stop].join("\n");
  return { destinataire: el.destinataire, expediteur_nom: `${nom} via BoostImpact`, sujet, html, texte: avecPied(texte, lg), desinscription: stop };
}

