// detail (service_du_jour, schema.sql) : a_faire (étapes restantes), et depuis le 26/10/2026 total (étapes de ce commerce : 3 en Essentiel, 4 sinon)
// et offre_id. Sans total (base pas encore à jour) : celui de l'offre, sinon 4 comme avant. Une étape « metricool » n'est jamais citée à une offre
// sans réseaux, même si la base la rendait.
// 27/10/2026 (bloc « Emails au commerçant » de schema.sql) : attente_equipe (["metricool"] tant que l'équipe n'a pas envoyé le lien : une phrase, pas
// une étape à faire) et lien_reseaux_le (date de l'envoi : l'aide de l'étape dit quel lien ouvrir).
function miseEnRouteEmail(el, ctx) {
  const lg = langueEmail(el.langue), T = TEXTES_MISE_EN_ROUTE[lg], C = COMMUN[lg], P = POINTS_LANGUES[lg], M = MISE_EN_PAGE, mots = M.MOTS[lg];
  const d = el.detail || {}, ordre = d.offre_id ? pointsOffre(d.offre_id) : ORDRE_POINTS;
  const nom = nettoyerNom(el.commerce), afaire = ordre.filter(k => (d.a_faire || []).includes(k)), url = adresse(ctx.urlEspace);
  if (!afaire.length) throw new Error("aucun point à faire");
  const attente = ordre.filter(k => k === "metricool" && (d.attente_equipe || []).includes(k) && !afaire.includes(k));
  const total = [3, 4].includes(+d.total) && +d.total >= afaire.length + attente.length ? +d.total : ordre.length;
  const n = afaire.length, sujet = T.sujet(n, nom), fait = Math.max(0, total - n - attente.length);
  const Pl = d.lien_reseaux_le ? Object.assign({}, P, { metricool: Object.assign({}, P.metricool, { aide: P.metricool.aideLien(dateLettres(d.lien_reseaux_le, lg)) }) }) : P;
  const etapes = etapesNumerotees(afaire, Pl, ordre), suite = attente.length ? P.metricool.attente : null;
  const html = M.courriel({ lg, titre: sujet, apercu: T.apercu(fait, total), repere: nom, h1: T.h1(n), chapo: T.chapo(nom),
    corps: [M.p(echapper(C.bonjour), { couleur: M.C.texte }), M.p(echapper(T.ou(nom, fait, total)), { marge: "0 0 12px 0" }), M.jauge(fait, total),
      M.p(echapper(T.reste(n)), { couleur: M.C.texte, style: "font-weight:600" }), M.etapes(etapes), suite ? M.p(echapper(suite), { taille: 15 }) : "", M.bouton(url, T.bouton),
      M.p(echapper(T.deja), { taille: 14, couleur: M.C.texteDiscret })],
    pied: [mots.client(nom), mots.stop] });
  const texte = [C.bonjour, "", T.ou(nom, fait, total), T.reste(n), "", ...etapesTexte(etapes), ...(suite ? ["", suite] : []), "", T.bouton + C.sep + url, "",
    T.deja, "", mots.question, mots.equipe, "", mots.client(nom), mots.stop].join("\n");
  return { destinataire: el.destinataire, sujet, html, texte: avecPied(texte, lg) };
}

