  const mois = MOIS_LANGUE[lg][+new Intl.DateTimeFormat("en-CA", { timeZone: "Europe/Paris", month: "2-digit" }).format(ctx.maintenant || new Date()) % 12];   // mois suivant, heure de Paris
  if (!d.offre || !d.offre_suivante || !(+d.plafond > 0) || !(+d.publications_suivante > 0)) throw new Error("offre incomplète");
  const sujet = T.sujet;
  const p1 = T.utilise(nom, d.plafond, nomOffre(d.offre_id, lg, d.offre), mois);
  const total = +d.publications_suivante + (+d.videos_suivante || 0), videos = +d.videos_suivante > 0 ? d.videos_suivante : 0, suivante = nomOffre(d.offre_suivante_id, lg, d.offre_suivante);
  const px = PRIX_OFFRES[d.offre_suivante_id], prix = px ? T.prix(px.annuel, px.mensuel) : null;
  const p2 = T.comprend(suivante, total, videos) + (prix ? " " + prix : "");
  const html = M.courriel({ lg, titre: sujet, apercu: T.apercu, repere: nom, h1: T.h1, chapo: T.chapo,
    corps: [M.p(echapper(C.bonjour), { couleur: M.C.texte }), M.p(echapper(p1), { marge: "0 0 24px 0" }),
      M.encart(T.titreOffre(suivante), M.p(echapper(T.contenuOffre(total, videos)), { marge: prix ? "0 0 8px 0" : "0", taille: 15 }) + (prix ? M.p(echapper(prix), { marge: "0", taille: 15 }) : "")),
      M.p(echapper(T.changer(suivante))), M.bouton(url, T.voir(suivante))],
    pied: [mots.client(nom), mots.stop] });
  const texte = [C.bonjour, "", p1, "", p2, "", T.changer(suivante), "", T.voir(suivante) + C.sep + url, "", mots.question, mots.equipe, "", mots.client(nom), mots.stop].join("\n");
  return { destinataire: el.destinataire, sujet, html, texte: avecPied(texte, lg) };
}

