const ENGAGEMENTS = { fiche_7j: "fiche optimisée sous 7 jours", premier_contenu_72h: "premier contenu proposé sous 72 h", avis_24h: "avis traité sous 24 h" };
const ALERTES_DELAI = { DELAI_FICHE_BIENTOT: "fiche à optimiser", DELAI_CONTENU_BIENTOT: "premier contenu à proposer", DELAI_AVIS_BIENTOT: "avis à traiter" };
// Mode de secours des avis (20/10/2026, clé « secours » de service_garanties, bloc « Mode de secours des avis » de schema.sql) : tant que l'API Google
// Business Profile n'est pas branchée, les réponses sont publiées à la main par l'équipe depuis la console (« À publier sur Google »).
const SECOURS = {
  AVIS_A_PUBLIER_ATTENTE: x => `- ${nettoyerNom(x.commerce) || "commerce"}, ${x.note} étoile${x.note > 1 ? "s" : ""} : réponse à publier sur Google depuis plus de ${x.heures} h${x.echeance ? `, avant le ${heureParis(x.echeance)} (garantie des 24 h)` : " (garantie déjà tenue : réponse validée par le commerçant)"}`,
  AVIS_NON_REDIGE: x => `- ${nettoyerNom(x.commerce) || "commerce"}, ${x.note} étoile${x.note > 1 ? "s" : ""} : avis relevé sans réponse rédigée depuis plus d'une heure (vérifier n8n, « RENOM, réponse aux avis relevés »), à traiter avant le ${heureParis(x.echeance)}`,
  RELEVE_AVIS_EN_PANNE: x => `- Relevé des avis arrêté : aucun relevé depuis le ${String(x.dernier_releve || "").slice(0, 16).replace("T", " ")} (UTC). Vérifier GitHub Actions (« Rendu RENOM », relevé des avis) et n8n. Si l'API Google est activée (RENOM_GBP_API = oui), c'est normal : ignorer.`,
  AVIS_NON_VISIBLES: x => `- ${nettoyerNom(x.commerce) || "commerce"} : ${pluriel(x.nombre, "nouvel avis", "nouveaux avis")} sur la fiche que le relevé n'a pas pu lire (Places ne rend que 5 avis) : ouvrir la fiche et y répondre à la main`,
};
function garantiesEmail(r, ctx) {
  const esc = (r && r.escalades) || [], tac = ((r && r.validations_tacites) || []).filter(x => !x.programme_le), rap = (r && r.rappels) || [];
  const al = ((r && r.delais) || {}).alertes || [], ma = ((r && r.delais) || {}).manquements || [], sec = ((r && r.secours) || []).filter(x => SECOURS[x.type]);
  if (!esc.length && !tac.length && !rap.length && !al.length && !ma.length && !sec.length) return null;
  const L = [];
  if (sec.length) L.push(`Avis Google, mode de secours (sans API) : ${pluriel(sec.length, "point", "points")} à traiter depuis la console, « À publier » :`, ...sec.map(x => SECOURS[x.type](x)), "");
  if (ma.length) L.push(`Garantie des délais : ${pluriel(ma.length, "engagement manqué", "engagements manqués")}. Mois offert à appliquer à la main dans Stripe (console, Avis et garanties) :`,
    ...ma.map(x => `- ${nettoyerNom(x.commerce) || "commerce"} : ${ENGAGEMENTS[x.engagement] || x.engagement}, échéance ${heureParis(x.echeance)}, mois offert : ${x.mois_offert}${x.nouveau_mois_offert ? "" : " (déjà offert pour ce mois)"}`), "");
  if (al.length) L.push(`Garantie des délais : ${pluriel(al.length, "échéance approche", "échéances approchent")} :`,
    ...al.map(x => `- ${nettoyerNom(x.commerce) || "commerce"} : ${ALERTES_DELAI[x.type] || x.type}${x.note ? ` (${x.note} étoile${x.note > 1 ? "s" : ""})` : ""}, avant le ${heureParis(x.echeance)}`), "");
  if (esc.length) L.push(`Croissance et Premium : ${pluriel(esc.length, "avis pris en charge", "avis pris en charge")} par l'équipe. Relire, publier depuis la console (file des avis) ; le commerçant est prévenu :`,
    ...esc.map(x => `- ${nettoyerNom(x.commerce) || "commerce"}, ${x.note} étoile${x.note > 1 ? "s" : ""}, à traiter avant le ${heureParis(x.echeance)}`), "");
  if (tac.length) L.push(`Mode délégation : ${pluriel(tac.length, "contenu validé", "contenus validés")} sans réponse en 48 h mais non ${tac.length > 1 ? "programmés" : "programmé"} (à programmer à la main) :`,
    ...tac.map(x => `- contenu ${x.contenu} : ${x.erreur || "raison inconnue"}`), "");
  const RAP = { OBJECTIF_PILOTE_J45: "J+45, objectif des 10 avis pas en vue", OBJECTIF_PILOTE_NON_ATTEINT: "échéance passée sans les 10 avis (objectif interne, aucune conséquence de facturation)" };
  if (rap.length) L.push("Objectif interne des pilotes (10 nouveaux avis en 60 jours, jamais affiché au client) :", ...rap.map(x => `- ${RAP[x.type] || x.type} (${x.gagnes} nouveaux avis, échéance ${x.echeance})`), "");
  const sujet = ma.length ? `BoostImpact : ${pluriel(ma.length, "engagement manqué", "engagements manqués")}, mois offert à appliquer`
    : al.length ? `BoostImpact : ${pluriel(al.length, "échéance", "échéances")} de la garantie à tenir`
    : sec.length ? `BoostImpact : avis Google, ${pluriel(sec.length, "point", "points")} à traiter à la main`
    : esc.length ? `BoostImpact : ${pluriel(esc.length, "avis à traiter", "avis à traiter")} sous 24 h` : rap.length ? "BoostImpact : objectif interne des pilotes" : "BoostImpact : contenus à programmer";
  const html = page(sujet, L.filter(x => x !== "").map(x => para(echapper(x))), "BoostImpact, alerte automatique (garanties).");
  return { destinataire: pourPJ(ctx), sujet, html, texte: avecPied(L.join("\n").trim()) };
}

// ---- Relance du commerçant (Essentiel seulement depuis le 22/10/2026) : une réponse d'avis attend sa validation depuis 4 h, puis 24 h. Le lien de l'email initial, s'il est
// encore ouvert ; sinon l'espace. Rien n'est publié sans lui (règle unique de publication) : l'email le dit. Langue : celle du commerce (relances_avis).
const TEXTES_RELANCE_AVIS = {
  fr: { sujet: (n, nom) => n === 1 ? `Un avis attend votre réponse, ${nom}` : `Rappel : un avis attend toujours votre réponse, ${nom}`,
    p1: note => `Un client a laissé un avis de ${pluriel(note, "étoile", "étoiles")} sur votre fiche Google. Notre réponse est prête : il vous suffit de la valider, de la modifier ou de la refuser.`,
    p2: "Rien n'est publié sans votre accord. Plus la réponse arrive vite, mieux elle est lue par les clients qui hésitent.", voir: "Voir la réponse",
    h1: n => n === 1 ? "Un avis attend votre réponse." : "Un avis attend toujours votre réponse.", chapo: "Notre réponse est prête. Il ne manque que votre accord.",
    apercu: "Notre réponse est prête : validez-la, modifiez-la ou refusez-la." },
  en: { sujet: (n, nom) => n === 1 ? `A review is awaiting your reply, ${nom}` : `Reminder: a review is still awaiting your reply, ${nom}`,
    p1: note => `A customer left a review of ${pluriel(note, "star", "stars")} on your Google profile. Our reply is ready: you just need to approve it, edit it or reject it.`,
    p2: "Nothing is published without your approval. The sooner the reply appears, the better it is read by customers who are hesitating.", voir: "See the reply",
    h1: n => n === 1 ? "A review is awaiting your reply." : "A review is still awaiting your reply.", chapo: "Our reply is ready. All it needs is your approval.",
    apercu: "Our reply is ready: approve it, edit it or reject it." },
  nl: { sujet: (n, nom) => n === 1 ? `Een review wacht op uw antwoord, ${nom}` : `Herinnering: een review wacht nog altijd op uw antwoord, ${nom}`,
    p1: note => `Een klant liet een review van ${pluriel(note, "ster", "sterren")} achter op uw Google-profiel. Ons antwoord staat klaar: u hoeft het alleen goed te keuren, aan te passen of te weigeren.`,
    p2: "Niets wordt gepubliceerd zonder uw akkoord. Hoe sneller het antwoord er staat, hoe beter het gelezen wordt door klanten die twijfelen.", voir: "Het antwoord bekijken",
    h1: n => n === 1 ? "Een review wacht op uw antwoord." : "Een review wacht nog altijd op uw antwoord.", chapo: "Ons antwoord staat klaar. Alleen uw akkoord ontbreekt nog.",
    apercu: "Ons antwoord staat klaar: keur het goed, pas het aan of weiger het." },
};
function relanceAvisEmail(el, ctx) {
  const lg = langueEmail(el.langue), T = TEXTES_RELANCE_AVIS[lg], C = COMMUN[lg], M = MISE_EN_PAGE, mots = M.MOTS[lg];
  const nom = nettoyerNom(el.commerce), n = +el.numero;
  if (![1, 2].includes(n)) throw new Error("numéro de relance d'avis inconnu");
  const url = /^[0-9a-f]{64}$/.test(el.jeton || "") ? adresse(ctx.urlEspace, "/valider.html#" + el.jeton) : adresse(ctx.urlEspace, "/#/avis");
  const sujet = T.sujet(n, nom);
  const p1 = T.p1(+el.note);
  const p2 = T.p2;
  const html = M.courriel({ lg, titre: sujet, apercu: T.apercu, repere: nom, h1: T.h1(n), chapo: T.chapo,
    corps: [M.p(echapper(C.bonjour), { couleur: M.C.texte }), M.p(echapper(p1)), M.p(echapper(p2)), M.bouton(url, T.voir)],
    pied: [mots.client(nom), mots.stop] });
  const texte = [C.bonjour, "", p1, "", p2, "", T.voir + C.sep + url, "", mots.question, mots.equipe, "", mots.client(nom), mots.stop].join("\n");
  return { destinataire: el.destinataire, sujet, html, texte: avecPied(texte, lg) };
}
// Tous les emails d'un passage de service_garanties : celui de PJ (s'il y a quelque chose à faire), puis les relances des commerçants.
function emailsGaranties(r, ctx) {
  const pj = garantiesEmail(r, ctx), out = pj ? [pj] : [];
  for (const el of (r && r.relances_avis) || []) {
    if (/^[^\s@<>"]+@[^\s@<>"]+\.[^\s@<>"]{2,}$/.test(el.destinataire || "")) out.push(relanceAvisEmail(el, ctx));
  }
  return out;
}

// ---- Aiguillage du service du jour : un élément de service_du_jour -> un email
const PAR_CATEGORIE = { demande_avis: demandeAvisEmail, relance_avis: demandeAvisEmail, mise_en_route: miseEnRouteEmail, relance_validation: relanceValidationEmail,
  relance_photos: relancePhotosEmail, offre_superieure: offreSuperieureEmail, alerte_mise_en_route: alerteMiseEnRouteEmail, relance_prospect: relanceProspectEmail, alerte_effacement: alerteEffacementEmail };
function emailDuJour(el, ctx) {
  const f = PAR_CATEGORIE[el && el.categorie]; if (!f) throw new Error("catégorie inconnue : " + (el && el.categorie));
  const e = f(el, ctx);
  if (!adressesEquipe(e.destinataire)) throw new Error("destinataire invalide");
  return e;
}

const ctx = {urlEspace: $vars.RENOM_URL_ESPACE, emailPJ: $vars.RENOM_EMAIL_PJ, rdvUrl: $vars.RENOM_RDV_URL, signature: $vars.RENOM_SIGNATURE};
// ---- Nœud « Rédiger le point » : point_hebdo (Supabase) -> un email à PJ.
const e = pointHebdoEmail($input.first().json, ctx);
return [{json: {destinataire: e.destinataire, sujet: e.sujet, html: e.html, texte: e.texte}}];

