      + `<td valign="top" style="padding:0 0 18px 0;border-bottom:1px solid ${C.or};font-family:${SANS};font-size:24px;font-weight:700;letter-spacing:-0.03em;line-height:1;color:${C.ivoire}" translate="no">boostimpact<span style="color:${C.or}">.</span><span style="font-weight:400;letter-spacing:-0.01em;color:${C.discretN}">agency</span></td>`
      + (o.repere ? `<td valign="top" align="right" style="padding:3px 0 18px 16px;border-bottom:1px solid ${C.or};font-family:${SANS};font-size:14px;line-height:1.35;color:${C.discretN}">${echapper(o.repere)}</td>` : "")
      + `</tr></table>`
