    deja: "Déjà fait ? Dites-le dans votre espace, sur l'accueil : BoostImpact vérifie et vous n'aurez plus ce rappel." },
  en: { sujet: (n, nom) => n > 1 ? `${nom}: ${n} steps left to get started` : `${nom}: one step left to get started`,
    h1: n => n > 1 ? `${n} steps to go.` : "One step to go.", chapo: nom => `Then we take it from there for ${nom}.`,
