    deja: "Already done? Say so in your account, on the home screen: BoostImpact checks and you will no longer get this reminder." },
  nl: { sujet: (n, nom) => n > 1 ? `${nom}: nog ${n} stappen om te starten` : `${nom}: nog één stap om te starten`,
    h1: n => n > 1 ? `Nog ${n} stappen.` : "Nog één stap.", chapo: nom => `Daarna nemen wij het over voor ${nom}.`,
    apercu: (f, t) => `Uw opstart staat op ${f} van ${t}. Dit moet nog gebeuren.`,
    ou: (nom, f, t) => `Uw opstart voor ${nom} staat op ${f} van ${t}.`, reste: n => n > 1 ? "Deze stappen moeten nog gebeuren:" : "Deze stap moet nog gebeuren:", bouton: "Mijn opstart afronden",
    deja: "Al gedaan? Laat het weten in uw klantenzone, op de startpagina: BoostImpact controleert het en u krijgt deze herinnering niet meer." },
