  const job = JSON.stringify(jobRelance(a.lien || a.place_id ? a : Object.assign({}, a, { place_id: null, lien: "LIEN_DE_LA_FICHE" })));
  const manuel = `Pour relancer : GitHub Actions, workflow « Rendu RENOM », Run workflow, champ job : ${job}`;
  let sujet, L;
