}
const majuscule = s => String(s).charAt(0).toUpperCase() + String(s).slice(1);
function bilanEmail(b, commerce, urlEspace) {
  const lg = langueEmail(commerce.langue), T = TEXTES_BILAN[lg], M = MISE_EN_PAGE, sep = lg === "fr" ? " : " : ": ";
  const nom = commerce.nom, mois = moisLettres(b.mois, lg), url = adresse(urlEspace), source = SOURCE_PERF.replace(/hl=fr$/, "hl=" + T.hl);
  const note = v => v == null ? T.nonLue : T.note(nombre(v, lg));
  const avis = b.avis_obtenus == null ? T.nonLus : b.avis_obtenus_source === "google" ? String(b.avis_obtenus) : T.avisBase(b.avis_obtenus);
  const fait = [[T.reponses, String(b.reponses_publiees)], [T.publications, String(b.publications)]];
  const finMois = premierDuMoisSuivant(b.mois, lg);
  const evolue = [[T.noteAu(premierDuMois(+String(b.mois).split("-")[1] - 1, lg)), note(b.note_debut)], [T.noteAu(finMois), note(b.note_fin)], [T.avisMois, avis]];
  const P = b.performance;
  if (P) {
    evolue.push([T.appels, String(P.appels || 0)], [T.itineraires, String(P.itineraires || 0)], [T.clicsSite, String(P.clics_site || 0)]);
    if (P.reservations) evolue.push([T.reservations, String(P.reservations)]);
  }
  const perfNote = P ? T.perfNote : "";
  const themes = (b.themes || []).filter(t => t && t.theme).map(t => [majuscule(t.theme), T.compte(t.positif || 0, t.negatif || 0)]);
  const Th = themes.map(([t, c]) => t + sep + c);
  const prochain = ameliorations(b, lg);
  const aValider = b.a_valider > 0, attente = aValider ? T.attente(b.a_valider) : T.rienAttente;
  const sujet = T.sujet(mois, nom), mots = M.MOTS[lg];
  const explication = b.avis_obtenus_source === "google" ? T.explicationGoogle : T.explicationBase;
  // Ce que le commerçant doit faire vient en premier : ce qui attend sa validation, avec le seul bouton de l'email ; sinon, le bouton ferme le bilan.
  const html = M.courriel({ lg, titre: sujet, apercu: T.apercu(+b.reponses_publiees || 0, +b.publications || 0), repere: nom, h1: T.h1(mois), chapo: T.chapo(nom),
    faits: [[T.fReponses, String(b.reponses_publiees)], [T.fPublications, String(b.publications)], [T.fNote(finMois), majuscule(note(b.note_fin))]],
    corps: [M.p(echapper(T.bonjour), { couleur: M.C.texte }), M.p(echapper(T.voici(mois, nom)), { marge: "0 0 24px 0" }),
      aValider ? M.encart(attente, M.p(echapper(T.attenteSuite(b.a_valider)), { marge: "0", taille: 15 }) + M.bouton(url, T.valider, { marge: "14px 0 0 0" }), "0 0 32px 0") : "",
      M.h2(T.fait), M.lignes(fait),
      M.h2(T.evolue), M.lignes(evolue),
      P ? M.p(echapper(perfNote) + " " + M.lienTexte(source, T.aide, M.C.texteDiscret), { marge: "-4px 0 28px 0", taille: 13, couleur: M.C.texteDiscret }) : "",
      themes.length ? M.h2(T.disent) + M.liste(themes) : "",
      M.h2(T.ameliorons), M.liste(prochain.map(x => [x, ""]), false),
      aValider ? "" : M.p(echapper(attente), { couleur: M.C.texte, style: "font-weight:600" }) + M.bouton(url, T.ouvrir),
      M.p(echapper(explication), { marge: "0 0 8px 0", taille: 13, couleur: M.C.texteDiscret })],
    pied: [T.pied] });
  const texte = [T.bonjour, ``, T.voici(mois, nom), ``,
    ...(aValider ? [attente + " " + T.attenteSuite(b.a_valider), T.valider + sep + url, ``] : []),
    T.fait, ...fait.map(([l, v]) => `${l}${sep}${v}`), ``,
    T.evolue, ...evolue.map(([l, v]) => `${l}${sep}${v}`), ...(P ? [perfNote + T.source + source] : []), ``,
    ...(themes.length ? [T.disent, ...Th, ``] : []),
    T.ameliorons, ...prochain, ``,
    ...(aValider ? [] : [attente, T.espace + url, ``]),
    explication, ``, mots.question, mots.equipe, ``,
    T.pied].join("\n");
  return { sujet, html, texte: avecPied(texte, lg) };
}

// ---- Contenus à valider : items = [{jeton, objet: "contenu"|"avis"|"commentaire", expire_le, contenu: {type, format, legende, publication_auto_le},
//      avis: {note, texte}, commentaire: {reseau, texte}}] ; commerce = {nom, langue, delegation_offre}. Validation SANS mot de passe : chaque lien
//      (valider.html#<jeton>) sert une fois.
// Texte selon l'offre (27/10/2026, audit du parcours, constat 17 ; CGV article 8) : « Rien n'est publié sans votre accord. » seulement quand c'est
// vrai. Mode délégation du Premium signé : chaque contenu porte contenu.publication_auto_le (notifications_validation_du_soir, schema.sql : envoi
// + 48 h) et l'email dit « Sans réponse de votre part, ce contenu sera publié à partir du <date heure> » (« à partir du » : la validation tacite
