// de promis (l'équipe peut répondre aux commentaires du Premium). Sinon, la phrase d'avant.
const TEXTES_VALIDATION = {
  fr: { commentaire: "Réponse à un commentaire", avis: "Réponse à un avis", etoiles: ["étoile", "étoiles"], story: "Story", video: "Vidéo", publication: "Publication", avisVide: "Avis sans texte",
    commentaireVide: "Commentaire", contenus: ["contenu", "contenus"], reponses: ["réponse d'avis", "réponses d'avis"], elements: ["élément", "éléments"], sujet: (q, n) => `${q} à valider pour ${n}`,
    attend: (q, n, plus) => `${q} ${plus ? "attendent" : "attend"} votre validation pour ${n}. Un clic suffit, sans mot de passe.`, voir: "Voir et valider",
    h1: (n, q) => (n === 1 ? q.replace(/^1 contenu/, "Un contenu").replace(/^1 réponse/, "Une réponse").replace(/^1 élément/, "Un élément") : q) + " à valider.", chapo: "Rien n'est publié sans votre accord.", apercu: (q, n) => `${q} pour ${n}. Un clic suffit, sans mot de passe.`,
    expire: d => `Chaque lien sert une seule fois et expire le ${d}.`, aussi: l => `Vous pouvez aussi tout valider depuis ${l}.`, votreEspace: "votre espace", espace: "Votre espace : ", separateur: " : ",
    transfert: "Ne transférez pas ce message : chaque lien permet de valider à votre place.",
    auto1: d => `Sans réponse de votre part, ce contenu sera publié à partir du ${d}.`, autoN: "Sans réponse de votre part, chaque contenu sera publié à partir de la date indiquée.",
    auto: d => `Sans réponse de votre part : publié à partir du ${d}.` },
  en: { commentaire: "Reply to a comment", avis: "Reply to a review", etoiles: ["star", "stars"], story: "Story", video: "Video", publication: "Post", avisVide: "Review without text",
    commentaireVide: "Comment", contenus: ["post", "posts"], reponses: ["review reply", "review replies"], elements: ["item", "items"], sujet: (q, n) => `${q} to approve for ${n}`,
    attend: (q, n, plus) => `${q} ${plus ? "are" : "is"} awaiting your approval for ${n}. One click is enough, no password needed.`, voir: "View and approve",
    h1: (n, q) => (n === 1 ? q.replace(/^1 /, "One ") : q) + " to approve.", chapo: "Nothing is published without your approval.", apercu: (q, n) => `${q} for ${n}. One click is enough, no password needed.`,
    expire: d => `Each link can be used only once and expires on ${d}.`, aussi: l => `You can also approve everything from ${l}.`, votreEspace: "your account", espace: "Your account: ", separateur: ": ",
    transfert: "Do not forward this message: each link lets someone approve on your behalf.",
    auto1: d => `If you do not reply, this post will be published from ${d}.`, autoN: "If you do not reply, each post will be published from the date shown.",
    auto: d => `If you do not reply: published from ${d}.` },
  nl: { commentaire: "Antwoord op een reactie", avis: "Antwoord op een review", etoiles: ["ster", "sterren"], story: "Story", video: "Video", publication: "Post", avisVide: "Review zonder tekst",
    commentaireVide: "Reactie", contenus: ["post", "posts"], reponses: ["antwoord op een review", "antwoorden op reviews"], elements: ["item", "items"], sujet: (q, n) => `${q} om goed te keuren voor ${n}`,
    attend: (q, n, plus) => `${q} ${plus ? "wachten" : "wacht"} op uw goedkeuring voor ${n}. Eén klik volstaat, zonder wachtwoord.`, voir: "Bekijken en goedkeuren",
    h1: (n, q) => (n === 1 ? q.replace(/^1 /, "Eén ") : q) + " om goed te keuren.", chapo: "Niets wordt gepubliceerd zonder uw akkoord.", apercu: (q, n) => `${q} voor ${n}. Eén klik volstaat, zonder wachtwoord.`,
    expire: d => `Elke link werkt maar één keer en verloopt op ${d}.`, aussi: l => `U kunt ook alles goedkeuren vanuit ${l}.`, votreEspace: "uw klantenzone", espace: "Uw klantenzone: ", separateur: ": ",
    transfert: "Stuur dit bericht niet door: met elke link kan iemand in uw plaats goedkeuren.",
    auto1: d => `Zonder antwoord van u wordt deze post gepubliceerd vanaf ${d}.`, autoN: "Zonder antwoord van u wordt elke post gepubliceerd vanaf de vermelde datum.",
    auto: d => `Zonder antwoord van u: gepubliceerd vanaf ${d}.` },
