// Ce que nous améliorons le mois prochain (ce qui attend la validation du commerçant n'y est plus : c'est l'action, en tête du bilan, 20/10/2026).
function ameliorations(b, lg) {
  const T = TEXTES_BILAN[langueEmail(lg)];
  const l = (b.ameliorations || []).map(x => String(x).trim()).filter(Boolean);
  if (b.note_debut != null && b.note_fin != null && b.note_fin < b.note_debut) l.push(T.baisse);
  const neg = (b.themes || []).filter(t => t.negatif > t.positif).map(t => t.theme);
  if (neg.length) l.push(T.themesNegatifs(neg));
  if (!l.length) l.push(T.rythme);
