    pied: n => `Cet email vous est envoyé par BoostImpact pour le compte de ${n}, parce que vous lui avez donné votre accord pour être contacté après votre visite. Ne plus recevoir de demande de ${n} : `,
    bouton: "Donner mon avis", merci: "Merci d'avance," },
  en: { sujetRelance: n => `Your opinion of ${n}, our only reminder`, sujet: n => `Your opinion of ${n}`, bonjour: p => `Hello${p ? " " + p : ""},`,
    relance: n => `A few days ago, ${n} asked for your opinion of your visit. If you have a moment, it is still welcome. This is our only reminder.`,
    demande: n => `Thank you for visiting ${n}. Your opinion, whatever it is, helps us improve and helps other people find us.`,
    pied: n => `This email is sent to you by BoostImpact on behalf of ${n}, because you agreed to be contacted after your visit. Stop receiving requests from ${n}: `,
    bouton: "Give my opinion", merci: "Thank you in advance," },
  nl: { sujetRelance: n => `Uw mening over ${n}, onze enige herinnering`, sujet: n => `Uw mening over ${n}`, bonjour: p => p ? `Dag ${p},` : "Goeiedag,",
    relance: n => `Enkele dagen geleden vroeg ${n} naar uw mening over uw bezoek. Als u even tijd hebt, is ze nog altijd welkom. Dit is onze enige herinnering.`,
    demande: n => `Bedankt voor uw bezoek aan ${n}. Uw mening, wat ze ook is, helpt ons om beter te worden en helpt anderen om ons te vinden.`,
    pied: n => `Deze e-mail wordt u door BoostImpact gestuurd namens ${n}, omdat u ermee hebt ingestemd na uw bezoek gecontacteerd te worden. Geen verzoeken meer ontvangen van ${n}: `,
    bouton: "Mijn mening geven", merci: "Alvast bedankt," },
