  const sujet = ma.length ? `BoostImpact : ${pluriel(ma.length, "engagement manqué", "engagements manqués")}, mois offert à appliquer`
    : al.length ? `BoostImpact : ${pluriel(al.length, "échéance", "échéances")} de la garantie à tenir`
    : sec.length ? `BoostImpact : avis Google, ${pluriel(sec.length, "point", "points")} à traiter à la main`
    : esc.length ? `BoostImpact : ${pluriel(esc.length, "avis à traiter", "avis à traiter")} sous 24 h` : rap.length ? "BoostImpact : objectif interne des pilotes" : "BoostImpact : contenus à programmer";
  const html = page(sujet, L.filter(x => x !== "").map(x => para(echapper(x))), "BoostImpact, alerte automatique (garanties).");
  return { destinataire: pourPJ(ctx), sujet, html, texte: avecPied(L.join("\n").trim()) };
}

// ---- Relance du commerçant (Essentiel seulement depuis le 22/10/2026) : une réponse d'avis attend sa validation depuis 4 h, puis 24 h. Le lien de l'email initial, s'il est
// encore ouvert ; sinon l'espace. Rien n'est publié sans lui (règle unique de publication) : l'email le dit. Langue : celle du commerce (relances_avis).
const TEXTES_RELANCE_AVIS = {
  fr: { sujet: (n, nom) => n === 1 ? `Un avis attend votre réponse, ${nom}` : `Rappel : un avis attend toujours votre réponse, ${nom}`,
    p1: note => `Un client a laissé un avis de ${pluriel(note, "étoile", "étoiles")} sur votre fiche Google. Notre réponse est prête : il vous suffit de la valider, de la modifier ou de la refuser.`,
    p2: "Rien n'est publié sans votre accord. Plus la réponse arrive vite, mieux elle est lue par les clients qui hésitent.", voir: "Voir la réponse",
    h1: n => n === 1 ? "Un avis attend votre réponse." : "Un avis attend toujours votre réponse.", chapo: "Notre réponse est prête. Il ne manque que votre accord.",
    apercu: "Notre réponse est prête : validez-la, modifiez-la ou refusez-la." },
  en: { sujet: (n, nom) => n === 1 ? `A review is awaiting your reply, ${nom}` : `Reminder: a review is still awaiting your reply, ${nom}`,
    p1: note => `A customer left a review of ${pluriel(note, "star", "stars")} on your Google profile. Our reply is ready: you just need to approve it, edit it or reject it.`,
    p2: "Nothing is published without your approval. The sooner the reply appears, the better it is read by customers who are hesitating.", voir: "See the reply",
    h1: n => n === 1 ? "A review is awaiting your reply." : "A review is still awaiting your reply.", chapo: "Our reply is ready. All it needs is your approval.",
    apercu: "Our reply is ready: approve it, edit it or reject it." },
  nl: { sujet: (n, nom) => n === 1 ? `Een review wacht op uw antwoord, ${nom}` : `Herinnering: een review wacht nog altijd op uw antwoord, ${nom}`,
    p1: note => `Een klant liet een review van ${pluriel(note, "ster", "sterren")} achter op uw Google-profiel. Ons antwoord staat klaar: u hoeft het alleen goed te keuren, aan te passen of te weigeren.`,
    p2: "Niets wordt gepubliceerd zonder uw akkoord. Hoe sneller het antwoord er staat, hoe beter het gelezen wordt door klanten die twijfelen.", voir: "Het antwoord bekijken",
    h1: n => n === 1 ? "Een review wacht op uw antwoord." : "Een review wacht nog altijd op uw antwoord.", chapo: "Ons antwoord staat klaar. Alleen uw akkoord ontbreekt nog.",
    apercu: "Ons antwoord staat klaar: keur het goed, pas het aan of weiger het." },
};
function relanceAvisEmail(el, ctx) {
  const lg = langueEmail(el.langue), T = TEXTES_RELANCE_AVIS[lg], C = COMMUN[lg], M = MISE_EN_PAGE, mots = M.MOTS[lg];
  const nom = nettoyerNom(el.commerce), n = +el.numero;
  if (![1, 2].includes(n)) throw new Error("numéro de relance d'avis inconnu");
  const url = /^[0-9a-f]{64}$/.test(el.jeton || "") ? adresse(ctx.urlEspace, "/valider.html#" + el.jeton) : adresse(ctx.urlEspace, "/#/avis");
  const sujet = T.sujet(n, nom);
  const p1 = T.p1(+el.note);
  const p2 = T.p2;
  const html = M.courriel({ lg, titre: sujet, apercu: T.apercu, repere: nom, h1: T.h1(n), chapo: T.chapo,
    corps: [M.p(echapper(C.bonjour), { couleur: M.C.texte }), M.p(echapper(p1)), M.p(echapper(p2)), M.bouton(url, T.voir)],
    pied: [mots.client(nom), mots.stop] });
  const texte = [C.bonjour, "", p1, "", p2, "", T.voir + C.sep + url, "", mots.question, mots.equipe, "", mots.client(nom), mots.stop].join("\n");
  return { destinataire: el.destinataire, sujet, html, texte: avecPied(texte, lg) };
}
// Tous les emails d'un passage de service_garanties : celui de PJ (s'il y a quelque chose à faire), puis les relances des commerçants.
function emailsGaranties(r, ctx) {
  const pj = garantiesEmail(r, ctx), out = pj ? [pj] : [];
  for (const el of (r && r.relances_avis) || []) {
    if (/^[^\s@<>"]+@[^\s@<>"]+\.[^\s@<>"]{2,}$/.test(el.destinataire || "")) out.push(relanceAvisEmail(el, ctx));
  }
  return out;
}

// ---- Aiguillage du service du jour : un élément de service_du_jour -> un email
const PAR_CATEGORIE = { demande_avis: demandeAvisEmail, relance_avis: demandeAvisEmail, mise_en_route: miseEnRouteEmail, relance_validation: relanceValidationEmail,
  relance_photos: relancePhotosEmail, offre_superieure: offreSuperieureEmail, alerte_mise_en_route: alerteMiseEnRouteEmail, relance_prospect: relanceProspectEmail, alerte_effacement: alerteEffacementEmail };
function emailDuJour(el, ctx) {
  const f = PAR_CATEGORIE[el && el.categorie]; if (!f) throw new Error("catégorie inconnue : " + (el && el.categorie));
  const e = f(el, ctx);
  if (!adressesEquipe(e.destinataire)) throw new Error("destinataire invalide");
  return e;
}

// Réponse d'un prospect à l'email « fiche à confirmer » (25/10/2026, décision de PJ : « je ne reçois pas de réponse après avoir validé que c'était
// bien l'une de ces fiches, ce n'est pas normal »). Lit la réponse (numéro de la fiche proposée, ou lien Google) et prépare la relance de l'audit
// (même chemin que la demande du site : GitHub Actions, rendu.yml, job de type audit). Recopié tel quel dans les nœuds Code de
// n8n/renom-prospects.json (n8n/build_automatisations.py), testé par moteur/tests/test_reponse_audit.js et moteur/tests/test_workflows_service.js.
// RÈGLE ANTI-ERREUR : dans le doute, rien n'est relancé et PJ est prévenu. Un audit sur la mauvaise fiche est pire qu'une réponse lue à la main.
//   - seule la partie NOUVELLE de la réponse est lue (le message cité, qui contient nos numéros, nos liens et des dates, est coupé) ;
//   - un lien Google dans cette partie l'emporte (le prospect donne sa fiche) ;
//   - sinon un numéro : un seul nombre dans la réponse (« 1 », « la 1 », « n° 2 ») ou un ordinal (« la première », « the second one »,
//     « de eerste ») ; deux nombres différents, un nombre hors 1 à 9, ou une négation (« non », « pas », « aucune », « none », « geen »…) : illisible.
//   La base (reponse_prospect, espace/supabase/schema.sql) vérifie ensuite que le numéro correspond à une fiche proposée et la limite de 3 par 24 h.

// Formats de lien Google acceptés : la MÊME expression que n8n/build_audit.py (JS_GOOGLE), site/app.js (GOOGLE) et moteur/audit/lien_google.py
// (FORMAT) ; moteur/tests/test_reponse_audit.js vérifie qu'elles sont identiques.
const GOOGLE_LIEN = /^https?:\/\/(?:(?:www\.)?google\.(?:[a-z]{2,3}|co\.[a-z]{2}|com\.[a-z]{2})\/(?:maps|search)(?:[\/?#]|$)|maps\.google\.(?:[a-z]{2,3}|co\.[a-z]{2}|com\.[a-z]{2})(?:[\/?#]|$)|(?:share\.google|g\.co|maps\.app\.goo\.gl|g\.page|business\.google\.com)\/|goo\.gl\/maps(?:[\/?#]|$))[^\s"<>]*$/i;
const GOOGLE_SANS_SCHEMA = /^(?:share\.google|g\.co|maps\.app\.goo\.gl|goo\.gl|g\.page|business\.google\.com|(?:www\.|maps\.)?google\.)/i;
const sansAccents = s => String(s == null ? "" : s).normalize("NFD").replace(/[̀-ͯ]/g, "").toLowerCase();

// Partie nouvelle d'une réponse : tout ce qui précède la citation (ligne « > », en-tête « Le … a écrit : », « On … wrote: », « Op … schreef: »,
// « -----Original Message----- », bloc « De : / From: / Van: » des messageries de bureau). En-tête coupé sur deux lignes : la ligne d'avant compte.
function partieNouvelle(texte) {
  const lignes = String(texte == null ? "" : texte).replace(/\r\n?/g, "\n").split("\n");
  let fin = lignes.length;
  for (let i = 0; i < lignes.length; i++) {
    const brut = lignes[i].trim(), n = sansAccents(brut);
    if (/^>/.test(brut) || /^-{2,}\s*(original|message d'origine|oorspronkelijk|forwarded|message transfere)/.test(n) || /^_{5,}$/.test(brut)
      || /^(de|from|van|von|envoye|sent|verzonden|objet|subject|onderwerp)\s*:/.test(n)) { fin = i; break; }
    if (/(a ecrit|wrote|schreef|schrieb|escribio)\s*:?\s*$/.test(n)) {
      fin = i > 0 && /^(le|on|op|am|el)\b/.test(sansAccents(lignes[i - 1].trim())) && !/^(le|on|op|am|el)\b/.test(n) ? i - 1 : i;
      break;
    }
  }
  return lignes.slice(0, fin).join("\n").trim();
}

const ORDINAUX = [[1, /\b(premiere|premier|1re|1ere|1er|first|1st|eerste)\b/], [2, /\b(deuxieme|seconde|second|2e|2eme|2nde|2nd|tweede)\b/]];
// Mois (français, anglais, néerlandais, formes courtes comprises), sans accents.
const MOIS_REPONSE = "janv|janvier|fevr|fevrier|mars|avr|avril|mai|juin|juil|juillet|aout|sept|septembre|oct|octobre|nov|novembre|dec|decembre|jan|january|feb|february|march|"
  + "apr|april|may|june|july|aug|august|sep|september|october|november|december|januari|februari|maart|mei|juni|juli|augustus|okt|oktober";
const NEGATIONS =/\b(non|pas|aucune|aucun|ni|none|neither|not|geen|niet|nee|neen|nope)\b/;

// Ce qu'on tire de la réponse : { numero (1 à 9) ou null, lien (Google, https) ou null, extrait (début de la partie nouvelle, 300 caractères) }.
function lireReponseAudit(texte) {
  const nouveau = partieNouvelle(texte);
  const extrait = nouveau.replace(/\s+/g, " ").trim().slice(0, 300);
  // Lien : le premier lien Google de la partie nouvelle (« https:// » oublié : ajouté), ponctuation finale retirée, 500 caractères au plus.
  let lien = null;
  for (const brut of nouveau.split(/[\s<>"()\[\]]+/)) {
    let u = brut.replace(/[.,;:!?»']+$/, "");
    if (!/^https?:\/\//i.test(u) && GOOGLE_SANS_SCHEMA.test(u) && u.includes("/")) u = "https://" + u;
    if (u.length <= 500 && GOOGLE_LIEN.test(u)) { lien = u.replace(/^http:\/\//i, "https://"); break; }
  }
  // Numéro : liens, adresses email, heures et dates (« le 2 novembre », « November 2 », « 2 nov. ») retirés avant de compter les nombres.
  let n = " " + sansAccents(nouveau).replace(/https?:\/\/\S+|\S+@\S+/g, " ").replace(/\b\d{1,2}[:h]\d{2}\b/g, " heure ")
    .replace(new RegExp("\\b\\d{1,2}(er|st|nd|rd|th|e)?\\s+(" + MOIS_REPONSE + ")|\\b(" + MOIS_REPONSE + ")\\.?\\s+\\d{1,2}\\b", "g"), " date ") + " ";
  // Puis numéros de téléphone (8 caractères et plus), durées (« 2 h », « 10 minutes ») ; les nombres de 10 et plus (code postal, rue d'une
  // signature) ne comptent pas. Réponse longue (plus de 280 caractères) : elle est pour PJ, aucun numéro n'est pris.
  n = n.replace(/\+?\d[\d .\/-]{6,}\d/g, " tel ").replace(/\b\d{1,3}\s*(h|heures?|hours?|uur|min|minutes?|minuten)\b/g, " duree ");
  const vus = new Set();
  for (const [k, re] of ORDINAUX) if (re.test(n)) { vus.add(k); n = n.replace(new RegExp(re.source, "g"), " "); }
  // Nombre collé à un autre (« 1,5 », « 3,4 », « 25/10 », « 1-2 ») : réponse douteuse (marque « ? »), aucun numéro.
  for (const m of n.matchAll(/(?<!\w)\d+(?:[.,\/-]\d+)*(?!\w)/g)) {
    if (/[.,\/-]/.test(m[0])) vus.add("?"); else if (Number(m[0]) < 10) vus.add(Number(m[0]));
  }
  const numero = !lien && vus.size === 1 && n.trim().length <= 280 && !NEGATIONS.test(n) && [...vus][0] >= 1 ? [...vus][0] : null;
  return { numero, lien, extrait };
}

// Job de relance pour GitHub Actions (rendu.yml), à partir de ce que rend reponse_prospect : mêmes champs que la demande du site
// (n8n/build_audit.py, « Lancer l'audit ») ; place_id (fiche désignée par son numéro) ou lien_maps (lien donné en réponse).
function jobRelance(a) {
  const job = { type: "audit", commerce: String(a.commerce || ""), ville: String(a.ville || ""), email: String(a.email || ""),
    metier: ["restaurant", "beaute", "sport"].includes(a.metier) ? a.metier : "autre" };
  if (a.place_id) job.place_id = String(a.place_id);
  else if (a.lien) job.lien_maps = String(a.lien);
  job.langue = ["nl", "en"].includes(a.langue) ? a.langue : "fr";
  return job;
}

const ctx = {urlEspace: $vars.RENOM_URL_ESPACE, emailPJ: $vars.RENOM_EMAIL_PJ, rdvUrl: $vars.RENOM_RDV_URL, signature: $vars.RENOM_SIGNATURE};
// ---- Un prospect a répondu : PJ est prévenu (ses relances sont déjà arrêtées par reponse_prospect).
// Audit en attente (25/10/2026) : l'alerte dit si l'audit est relancé, ou « audit en attente : relancer avec … » (refus, appel en échec).
const r = $('Réponse notée (Supabase)').first().json, m = $('Lire la réponse').first().json, p = $('Préparer la relance').first().json, x = $input.first().json || {};
const e = reponseProspectEmail({expediteur: m.email, objet: m.objet, commerce: r.commerce, audit: r, lecture: m, relance_partie: p.relancer ? !x.error : null}, ctx);
return [{json: {destinataire: e.destinataire, sujet: e.sujet, html: e.html, texte: e.texte}}];

