      `<p style="margin:0 0 10px 0;font-family:${SANS};font-size:12px;line-height:1.5;color:${C.texteDiscret}">${x}</p>`).join("")}</td></tr>`;
    return `<!doctype html>\n<html lang="${HTML_LANG[lg]}"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1">`
      + `<meta name="x-apple-disable-message-reformatting"><meta name="color-scheme" content="light only"><meta name="supported-color-schemes" content="light only">`
      + `<title>${echapper(o.titre)}</title>\n<style>\n`
      + `@font-face{font-family:'Source Serif 4';font-style:normal;font-weight:400 600;src:url(${POLICES}source-serif-4.woff2) format('woff2')}\n`
      + `@font-face{font-family:'Schibsted Grotesk';font-style:normal;font-weight:400 700;src:url(${POLICES}schibsted-grotesk.woff2) format('woff2')}\n`
      + `h1,h2{font-variation-settings:'opsz' 48}\n`
      + `:root{color-scheme:light only;supported-color-schemes:light only}\n`
      + `a[x-apple-data-detectors]{color:inherit!important;text-decoration:none!important}\n`
      + `@media (max-width:480px){.px{padding-left:20px!important;padding-right:20px!important}.h1{font-size:36px!important}}\n`
      + `</style></head>\n<body style="margin:0;padding:0;background-color:${C.clair};color:${C.texte};-webkit-text-size-adjust:100%" bgcolor="${C.clair}">\n`
      + `<div style="display:none;max-height:0;max-width:0;overflow:hidden;opacity:0;mso-hide:all;color:${C.clair}">${echapper(o.apercu)}${"&#847;&zwnj;&nbsp;".repeat(40)}</div>\n`
      + `<table role="presentation" width="100%" cellpadding="0" cellspacing="0" border="0" bgcolor="${C.clair}" style="background-color:${C.clair}"><tr><td align="center" style="padding:24px 8px">\n`
      + `<table role="presentation" width="600" cellpadding="0" cellspacing="0" border="0" style="width:100%;max-width:600px">\n${typo(entete)}\n${typo(corps)}\n${pied}\n</table>\n`
      + `</td></tr></table>\n</body></html>\n`;
  }
  return { C, SERIF, SANS, POLICES, MOTS, p, h2, lienTexte, bouton, etapes, liste, lignes, encart, jauge, carte, faits, espace, courriel };
})();
const lien = (href, texte) => `<a href="${echapper(href)}" style="color:${ENCRE};text-decoration:underline">${echapper(texte)}</a>`;
function tableau(lignes) {
  return `<tr><td style="padding:0 0 16px 0"><table role="presentation" width="100%" cellspacing="0" cellpadding="0">${lignes.map(([l, v]) =>
    `<tr><td style="padding:10px 0;border-bottom:1px solid ${FILET}">${echapper(l)}</td><td align="right" style="padding:10px 0;border-bottom:1px solid ${FILET};font-weight:600">${echapper(v)}</td></tr>`).join("")}</table></td></tr>`;
}

