// ---- Garanties (n8n/renom-garanties.json, toutes les heures) : résultat de service_garanties -> UN email à PJ, ou null s'il n'y a rien à faire.
// Trois offres (16/10/2026) : avis Standard et Premium (22/10/2026) pris en charge par l'équipe (à publier avant l'échéance des 24 h) ; contenus Premium publiés en mode délégation
// qui n'ont pas pu être programmés ; garantie des délais (alertes AVANT dépassement, manquements = mois offert à appliquer à la main dans Stripe) ;
// objectif interne des pilotes (ancienne garantie « 10 avis », sans conséquence de facturation). Rien d'autre.
const heureParis = iso => new Date(iso).toLocaleString("fr-FR", { day: "numeric", month: "long", hour: "2-digit", minute: "2-digit", timeZone: "Europe/Paris" });
const ENGAGEMENTS = { fiche_7j: "fiche optimisée sous 7 jours", premier_contenu_72h: "premier contenu proposé sous 72 h", avis_24h: "avis traité sous 24 h" };
const ALERTES_DELAI = { DELAI_FICHE_BIENTOT: "fiche à optimiser", DELAI_CONTENU_BIENTOT: "premier contenu à proposer", DELAI_AVIS_BIENTOT: "avis à traiter" };
// Mode de secours des avis (20/10/2026, clé « secours » de service_garanties, bloc « Mode de secours des avis » de schema.sql) : tant que l'API Google
// Business Profile n'est pas branchée, les réponses sont publiées à la main par l'équipe depuis la console (« À publier sur Google »).
const SECOURS = {
  AVIS_A_PUBLIER_ATTENTE: x => `- ${nettoyerNom(x.commerce) || "commerce"}, ${x.note} étoile${x.note > 1 ? "s" : ""} : réponse à publier sur Google depuis plus de ${x.heures} h${x.echeance ? `, avant le ${heureParis(x.echeance)} (garantie des 24 h)` : " (garantie déjà tenue : réponse validée par le commerçant)"}`,
  AVIS_NON_REDIGE: x => `- ${nettoyerNom(x.commerce) || "commerce"}, ${x.note} étoile${x.note > 1 ? "s" : ""} : avis relevé sans réponse rédigée depuis plus d'une heure (vérifier n8n, « RENOM, réponse aux avis relevés »), à traiter avant le ${heureParis(x.echeance)}`,
  RELEVE_AVIS_EN_PANNE: x => `- Relevé des avis arrêté : aucun relevé depuis le ${String(x.dernier_releve || "").slice(0, 16).replace("T", " ")} (UTC). Vérifier GitHub Actions (« Rendu RENOM », relevé des avis) et n8n. Si l'API Google est activée (RENOM_GBP_API = oui), c'est normal : ignorer.`,
  AVIS_NON_VISIBLES: x => `- ${nettoyerNom(x.commerce) || "commerce"} : ${pluriel(x.nombre, "nouvel avis", "nouveaux avis")} sur la fiche que le relevé n'a pas pu lire (Places ne rend que 5 avis) : ouvrir la fiche et y répondre à la main`,
};
function garantiesEmail(r, ctx) {
  const esc = (r && r.escalades) || [], tac = ((r && r.validations_tacites) || []).filter(x => !x.programme_le), rap = (r && r.rappels) || [];
  const al = ((r && r.delais) || {}).alertes || [], ma = ((r && r.delais) || {}).manquements || [], sec = ((r && r.secours) || []).filter(x => SECOURS[x.type]);
  if (!esc.length && !tac.length && !rap.length && !al.length && !ma.length && !sec.length) return null;
  const L = [];
  if (sec.length) L.push(`Avis Google, mode de secours (sans API) : ${pluriel(sec.length, "point", "points")} à traiter depuis la console, « À publier » :`, ...sec.map(x => SECOURS[x.type](x)), "");
  if (ma.length) L.push(`Garantie des délais : ${pluriel(ma.length, "engagement manqué", "engagements manqués")}. Mois offert à appliquer à la main dans Stripe (console, Avis et garanties) :`,
    ...ma.map(x => `- ${nettoyerNom(x.commerce) || "commerce"} : ${ENGAGEMENTS[x.engagement] || x.engagement}, échéance ${heureParis(x.echeance)}, mois offert : ${x.mois_offert}${x.nouveau_mois_offert ? "" : " (déjà offert pour ce mois)"}`), "");
  if (al.length) L.push(`Garantie des délais : ${pluriel(al.length, "échéance approche", "échéances approchent")} :`,
