const ctx = {urlEspace: $vars.RENOM_URL_ESPACE, emailPJ: $vars.RENOM_EMAIL_PJ, rdvUrl: $vars.RENOM_RDV_URL, signature: $vars.RENOM_SIGNATURE};
const de = e => { const x = String($vars.RENOM_EXPEDITEUR || '').trim(), m = x.match(/<([^<>]+)>\s*$/), a = (m ? m[1] : x).trim();
  return e.expediteur_nom ? '"' + String(e.expediteur_nom).replace(/["<>\r\n]/g, '') + '" <' + a + '>' : m ? x : '"BoostImpact" <' + a + '>'; };
// ---- Nœud « Rédiger les emails » : un élément de service_du_jour -> un email. Un élément impossible à rédiger n'est pas envoyé : il part
// directement au retour d'envoi comme un échec, avec la raison (rien n'est perdu, rien n'est renvoyé en boucle).
const r = $input.first().json, els = (r && r.elements) || [];
return els.map(el => { try { const e = emailDuJour(el, ctx); return {json: {cle: el.cle, categorie: el.categorie, destinataire: e.destinataire, de: de(e), sujet: e.sujet, html: e.html, texte: e.texte, erreur: null}}; }
  catch (x) { return {json: {cle: el.cle, categorie: el.categorie, erreur: 'rédaction impossible : ' + String(x.message || x)}}; } });

