  blocs.push(bloc(`<strong style="font-size:17px">${echapper(titre)}</strong>${p.distance_km != null ? `<br><span style="color:${GRIS};font-size:14px">${echapper(nombre(p.distance_km))} km à vol d'oiseau depuis l'étape précédente</span>` : ""}`, "padding-top:18px"));
  const adr = [p.adresse || [p.code_postal, p.commune].filter(Boolean).join(" ")].filter(Boolean).join("");
  const liens = [p.lien_maps ? lien(p.lien_maps, "Fiche Google Maps") : "", p.telephone ? `<a href="tel:${echapper(tel(p.telephone))}" style="color:${ENCRE};text-decoration:underline">${echapper(p.telephone)}</a>` : "Téléphone : absent de la fiche"].filter(Boolean).join(" &nbsp; ");
  blocs.push(bloc(`${echapper(adr)}<br>${liens}`));
  const score = p.score != null ? `Score : <strong>${p.score} sur 100</strong> (notre grille). Google : ${echapper(noteTexte(p))}.` : `Audit non fait aujourd'hui (plafond du jour). Google : ${echapper(noteTexte(p))}.`;
  blocs.push(bloc(score));
  if (p.priorites && p.priorites.length) blocs.push(bloc(`<strong>Les 3 priorités de l'audit</strong><br>${p.priorites.map((x, i) => `${i + 1}. ${echapper(x)}`).join("<br>")}`));
  if (p.raisons && p.raisons.length) blocs.push(petit(`Pourquoi ce commerce : ${echapper(p.raisons.join(" ; "))}.`));
  blocs.push(bloc(`<span style="color:${GRIS};font-size:14px">${p.canal === "visite" ? "À dire en entrant" : "À dire au téléphone"}</span><br>${echapper(p.accroche)}`));
  blocs.push(petit(`${echapper(p.a_regarder)} ${echapper(p.si_non)}`));
  blocs.push(petit(p.rapport ? `Rapport à remettre (ouvrir sur le téléphone) ou à transférer par email : pièce jointe <strong>${echapper(p.rapport)}</strong>.`
    : "Pas de rapport joint : l'audit se fait à la demande (formulaire de la page) si le gérant le veut."));
  blocs.push(boutons(ctx.urlEspace, p.jeton));
  txt.push(titre, adr, p.lien_maps ? "Google Maps : " + p.lien_maps : "", p.telephone ? "Téléphone : " + p.telephone : "Téléphone : absent de la fiche",
    p.score != null ? `Score : ${p.score} sur 100 (notre grille). Google : ${noteTexte(p)}.` : `Audit non fait aujourd'hui (plafond du jour). Google : ${noteTexte(p)}.`,
    ...(p.priorites || []).map((x, i) => `  ${i + 1}. ${x}`), p.raisons && p.raisons.length ? `Pourquoi : ${p.raisons.join(" ; ")}.` : "", "Accroche : " + p.accroche,
    p.a_regarder + " " + p.si_non, p.rapport ? "Rapport : pièce jointe " + p.rapport : "Pas de rapport joint.",
    "Résultat : " + RESULTATS.map(([c, t]) => `${t} ${lienResultat(ctx.urlEspace, c, p.jeton)}`).join(" | "), "");
}

function tourneeEmail(charge, ctx) {
  // RENOM_EMAIL_PJ : une adresse ou plusieurs séparées par des virgules (27/10/2026) ; la tournée part à l'équipe, jamais à un prospect.
  const equipe = adressesEquipe(ctx.emailPJ); if (!equipe) throw new Error("variable RENOM_EMAIL_PJ absente");
  adresse(ctx.urlEspace);   // refuse une adresse d'espace absente : les boutons « résultat » en dépendent
  const c = charge || {}, v = c.visites || [], a = c.appels || [], r = c.rappels || [], alertes = c.alertes || [];
  const quand = c.jour ? jourCourt(c.jour) : "";
  const sujet = c.statut === "erreur" ? `Tournée du ${quand} : impossible, voir le détail`
    : c.statut === "configuration" ? "Tournée du jour : codes postaux à remplir"
    : !v.length && !a.length ? `Tournée du ${quand} : aucun prospect${r.length ? `, ${pluriel(r.length, "rappel", "rappels")}` : ""}`
    : `Tournée du ${quand} : ${pluriel(v.length, "visite", "visites")}, ${pluriel(a.length, "appel", "appels")}${r.length ? `, ${pluriel(r.length, "rappel", "rappels")}` : ""}${c.arret ? " (arrêt avant la fin)" : ""}`;
  const blocs = [], txt = [];
  const intro = c.jour ? `Tournée du ${jourLong(c.jour)}.` : "Tournée du jour.";
  blocs.push(para(echapper(intro))); txt.push(intro, "");
  if (alertes.length) {
    blocs.push(para(`<strong>À savoir</strong><br>${alertes.map(echapper).join("<br>")}`));
    txt.push("À SAVOIR", ...alertes, "");
  }
  const k = c.compteur_jour || {}, cfg = c.config || {};
  if (c.statut !== "configuration" && c.statut !== "erreur") {
    const ap = Object.values(k.appels || {}).reduce((s, n) => s + Number(n || 0), 0);
    const chiffres = `Audits aujourd'hui : ${k.audits || 0} sur ${cfg.audits_max != null ? cfg.audits_max : "?"}. Fiches rapprochées : ${k.rapprochements || 0} sur ${cfg.rapprochements_max != null ? cfg.rapprochements_max : "?"}. `
      + `Appels Google Places du jour : ${ap}${c.cout && c.cout.usd_au_dela != null ? ` (0 $ dans le quota gratuit mensuel ; ${nombre(c.cout.usd_au_dela)} $ au-delà pour cette tournée)` : ""}.`;
    blocs.push(petit(echapper(chiffres))); txt.push(chiffres, "");
  }
  if (r.length) {
    blocs.push(para("<strong>À rappeler aujourd'hui</strong>", "padding-top:8px")); txt.push("À RAPPELER AUJOURD'HUI");
    r.forEach(x => {
      const l1 = `${x.nom}${x.commune ? ", " + x.commune : ""} : rappel ${x.numero} sur 3`;
      blocs.push(bloc(`<strong>${echapper(l1)}</strong><br>${x.telephone ? `<a href="tel:${echapper(tel(x.telephone))}" style="color:${ENCRE}">${echapper(x.telephone)}</a>` : "Téléphone : sur la fiche"}${x.lien_maps ? " &nbsp; " + lien(x.lien_maps, "Fiche Google Maps") : ""}${x.note_pj ? `<br><span style="color:${GRIS};font-size:14px">Vos notes : ${echapper(x.note_pj)}</span>` : ""}`, "padding-top:10px"));
      blocs.push(boutons(ctx.urlEspace, x.jeton));
      txt.push(l1, x.telephone ? "Téléphone : " + x.telephone : "", x.note_pj ? "Notes : " + x.note_pj : "", "Résultat : " + RESULTATS.map(([cc, t]) => `${t} ${lienResultat(ctx.urlEspace, cc, x.jeton)}`).join(" | "), "");
    });
  }
  if (v.length) {
    blocs.push(para(`<strong>Visites, dans l'ordre de passage</strong><br><span style="color:${GRIS};font-size:14px">Ordre : ${echapper(c.ordre_visite || "code postal puis adresse")}. Mardi à vendredi, 15 h à 17 h 30, jamais pendant un service.</span>`, "padding-top:12px"));
    txt.push("VISITES, DANS L'ORDRE DE PASSAGE (" + (c.ordre_visite || "code postal puis adresse") + ")", "");
    v.forEach(p => carte(p, ctx, blocs, txt));
  }
  if (a.length) {
    blocs.push(para(`<strong>Appels</strong><br><span style="color:${GRIS};font-size:14px">10 h à 11 h 30 et 15 h à 17 h. Numéro du commerce seulement.</span>`, "padding-top:12px"));
    txt.push("APPELS", "");
    a.forEach(p => carte(p, ctx, blocs, txt));
  }
  const regles = "Aucun email n'a été envoyé aux commerces : seul vous recevez ce message. Au premier contact, citez la source : le répertoire public des entreprises (Sirene) et la fiche Google. "
    + "Un « non » entre dans la liste d'opposition (bouton « Pas intéressé »). Score : notre grille, calculée sur ce que l'API de Google laisse voir ; les réponses du gérant aux avis n'y sont pas. "
    + "Notes, avis, téléphones et adresses de Google ne sont gardés nulle part ailleurs que dans cet email et les rapports joints.";
  blocs.push(petit(echapper(regles))); txt.push(regles);
  blocs.push(para(lien(adresse(ctx.urlEspace, "/console.html#/prospects"), "Ouvrir la console, onglet Prospects"))); txt.push("Console : " + adresse(ctx.urlEspace, "/console.html#/prospects"));
  return { destinataire: equipe, sujet, html: page(sujet, blocs, "BoostImpact, tournée automatique des jours ouvrés (7 h 30)."), texte: avecPied(txt.filter((x, i, l) => x !== "" || l[i - 1] !== "").join("\n")) };
}

// Pièces jointes pour le nœud d'email de n8n : un binaire par rapport (nom de propriété rapport_0, rapport_1...) et la liste de ces noms.
function piecesJointes(charge) {
  const binary = {}, noms = [];
  ((charge && charge.rapports) || []).forEach((x, i) => {
    if (!x || !x.html_b64 || !/^audit-[a-z0-9-]+\.html$/.test(x.nom_fichier || "")) return;
    const k = "rapport_" + i; noms.push(k);
    binary[k] = { data: x.html_b64, mimeType: "text/html", fileName: x.nom_fichier, fileExtension: "html" };
  });
  return { binary, pieces: noms.join(",") };
}

// ---- Nœud « Rédiger la tournée » : charge renvoyée par moteur/prospection/tournee.py -> UN email à PJ, rapports en pièces jointes.
const charge = ($input.first().json || {}).body || {};
const e = tourneeEmail(charge, {emailPJ: $vars.RENOM_EMAIL_PJ, urlEspace: $vars.RENOM_URL_ESPACE});
const p = piecesJointes(charge);
return [{json: {destinataire: e.destinataire, sujet: e.sujet, html: e.html, texte: e.texte, pieces: p.pieces}, binary: p.binary}];

new.jsCode:
// Emails de BoostImpact au commerçant : bilan du mois (le 1er) et « N contenus à valider ». HTML sobre et texte brut, dans la langue du commerce.
// Recopié tel quel dans les nœuds Code des workflows n8n (n8n/build_maj_membre.py) et testé par moteur/tests/test_courriels.js.
// Charte : pas d'emoji, pas de dégradé, pas d'orange, pas de vert, pas de trait coloré devant un libellé. Charte du site depuis le 24/10/2026
// (site/style.css, :root, validée par PJ le 21/10/2026) : bleu nuit #0F1C3A et ivoire #F6F4EF, accent bleu ardoise, titres en Source Serif 4,
// texte en Schibsted Grotesk. Emails au commerçant : mise en page commune MISE_EN_PAGE ci-dessous. Emails à PJ, demande d'avis, prospection : page(),
// sobre (bleu nuit, gris pierre, blanc ; Schibsted Grotesk, Arial en repli), sans mot-symbole. Testé aussi par moteur/tests/test_emails_gabarit.js.
// Aucun chiffre n'est inventé : une valeur absente (null) est dite « non lue », jamais remplacée.
// Langues (17/10/2026) : un email adressé à un commerçant ou à ses clients sort dans la langue du commerce (commerces.langue : « fr », « en »,
// « nl » = néerlandais de Belgique, vouvoiement « u ») ; toute autre valeur, ou aucune : français, identique octet pour octet à celui d'avant
// (moteur/tests/test_courriels_langues.js). Les emails à PJ restent en français.
const MOIS = ["janvier", "février", "mars", "avril", "mai", "juin", "juillet", "août", "septembre", "octobre", "novembre", "décembre"];
// page() : bleu nuit (--nuit), gris pierre (--pierre, 6,1:1 sur blanc), filet ivoire (--filet-clair), fond blanc ; valeurs de site/style.css.
const ENCRE = "#0F1C3A", GRIS = "#5D6270", FILET = "#D9DBE0", FOND = "#FFFFFF", IVOIRE = "#F6F4EF";
const SANS_PAGE = "'Schibsted Grotesk',Arial,Helvetica,sans-serif", POLICES_SITE = "https://boostimpact.agency/fonts/";
const langueEmail = x => x === "en" || x === "nl" ? x : "fr";
const MOIS_LANGUE = { fr: MOIS, en: ["January", "February", "March", "April", "May", "June", "July", "August", "September", "October", "November", "December"],
  nl: ["januari", "februari", "maart", "april", "mei", "juni", "juli", "augustus", "september", "oktober", "november", "december"] };
const LOCALE = { fr: "fr-FR", en: "en-GB", nl: "nl-BE" }, HTML_LANG = { fr: "fr", en: "en", nl: "nl-BE" };

const echapper = s => String(s == null ? "" : s).replace(/&/g, "&amp;").replace(/</g, "&lt;").replace(/>/g, "&gt;").replace(/"/g, "&quot;").replace(/'/g, "&#39;");
const nombre = (x, lg) => langueEmail(lg) === "en" ? String(x) : String(x).replace(".", ",");
const pluriel = (n, un, plusieurs) => n + " " + (n > 1 ? plusieurs : un);
function moisLettres(iso, lg) { const [a, m] = String(iso).split("-"); return MOIS_LANGUE[langueEmail(lg)][+m - 1] + " " + a; }
// « 1er octobre » en français, « 1 October », « 1 oktober » ; l'année seulement en changeant d'année.
function premierDuMois(m, lg) { return (langueEmail(lg) === "fr" ? "1er " : "1 ") + MOIS_LANGUE[langueEmail(lg)][(m + 12) % 12]; }
function premierDuMoisSuivant(iso, lg) { const [a, m] = String(iso).split("-").map(Number); return premierDuMois(m, lg) + (m === 12 ? " " + (a + 1) : ""); }
function dateLettres(iso, lg) { const d = new Date(iso); return d.toLocaleDateString(LOCALE[langueEmail(lg)], { day: "numeric", month: "long", timeZone: "Europe/Paris" }); }
// Date et heure de Paris en toutes lettres (27/10/2026) : « 28 octobre à 18 h », « 28 octobre à 18 h 05 » ; « 28 October at 18:00 (Paris time) » ;
// « 28 oktober om 18.00 uur ». Minute tronquée : l'heure écrite n'est jamais plus tard que l'heure réelle.
function dateHeure(iso, lg) {
  const l = langueEmail(lg), p = {};
  new Intl.DateTimeFormat("en-GB", { timeZone: "Europe/Paris", hour: "2-digit", minute: "2-digit", hourCycle: "h23" }).formatToParts(new Date(iso)).forEach(x => { p[x.type] = x.value; });
  const h = String(+p.hour), m = p.minute, j = dateLettres(iso, l);
  return l === "en" ? `${j} at ${p.hour}:${m} (Paris time)` : l === "nl" ? `${j} om ${h}.${m} uur` : `${j} à ${h} h${m === "00" ? "" : " " + m}`;
}
function adresse(urlEspace, suite) {
  const u = String(urlEspace || "").replace(/\/+$/, "");
  if (!/^https:\/\/[^\s"<>]+$/.test(u)) throw new Error("adresse de l'espace absente ou non https (variable RENOM_URL_ESPACE)");
  return u + (suite || "/");
}
// Adresses de l'équipe (variable n8n RENOM_EMAIL_PJ, 27/10/2026, audit du parcours, constat 26) : une adresse, ou plusieurs séparées par des virgules
// (ou des points-virgules) pour que PJ et Pascal reçoivent chacun chaque alerte. Rend « a@x.fr, b@y.be » (espaces retirés, sans doublon), ou null
// si la liste est vide ou si une adresse est invalide : l'alerte échoue alors (workflow d'erreur) au lieu de partir à moitié.
function adressesEquipe(x) {
  const l = String(x == null ? "" : x).split(/[,;]/).map(s => s.trim()).filter(Boolean);
  return l.length && l.every(s => /^[^\s@<>"]+@[^\s@<>"]+\.[^\s@<>"]{2,}$/.test(s)) ? [...new Set(l)].join(", ") : null;
}

// Pied légal de chaque email (site/legal.json, seule source ; règlement britannique 2015/17, règles 24 et 25 : nom, lieu d'immatriculation,
// numéro, siège). page() l'ajoute au HTML, avecPied() au texte brut. Dans les nœuds Code de n8n, la ligne « require » ci-dessous est remplacée
// par le contenu de legal.json (outils/legal.py, injecter_legal_js, appelé par n8n/build_*.py).
const LEGAL = {"_lisez_moi":"Source unique des mentions légales (pages de site/, pieds de page de site/ et de espace/web/, pieds légaux des emails du moteur et de n8n). Une valeur encore à compléter commence par l'un des marqueurs de outils/legal.py (MARQUES) et s'affiche en gras sur les pages. Après toute modification : python3 outils/legal.py (réécrit les pages), puis python3 n8n/build_automatisations.py, build_maj_membre.py, build_ordre10.py, build_audit.py et python3 moteur/avis/build_workflow.py (régénèrent les emails). Le test moteur/tests/test_legal.py refuse toute page en retard sur ce fichier.","nom_commercial":"BoostImpact","societe":{"denomination":"Girlden LTD","forme":"société à responsabilité limitée de droit anglais (private limited company)","numero":"14837617","registre":"Companies House","pays_immatriculation":"Angleterre et au pays de Galles","siege":"71-75 Shelton Street, Covent Garden, London WC2H 9JQ, Royaume-Uni","capital":"1 GBP (déclaration de capital à l'immatriculation, Companies House, 1er mai 2023)","tva":"Non assujettie à la TVA (prestataire non établi dans l'Union européenne ; autoliquidation par le Client)"},"directeur_publication":"Pierre-Jean Deàk Grisoni","contact":{"email":"info@boostimpact.agency","telephone":"sur demande, par email"},"site_url":"https://boostimpact.agency","hebergement":{"pages_production":"cloudflare_pages","fournisseurs":{"cloudflare_pages":{"nom":"Cloudflare, Inc. (service Cloudflare Pages)","adresse":"101 Townsend St., San Francisco, CA 94107, États-Unis","telephone":"+1 650 319 8930","source":"https://www.cloudflare.com/en/website-terms/ (lue le 25/10/2026)"},"supabase":{"nom":"Supabase Pte. Ltd.","adresse":"65 Chulia Street #38-02/03, OCBC Centre, Singapour 049513","telephone":"non publié (contact : legal@supabase.com)","source":"https://supabase.com/terms (lue le 13/10/2026, adresse présentée comme « place of business »)"}}},"documents":{"version":"29 octobre 2026"},"facturation":{"premier_mois":"en entier ; l'abonnement court ensuite de date à date, chaque mois ou chaque année selon le rythme de paiement choisi","moyen_paiement":"carte bancaire, par Stripe","taux_penalites":"taux de refinancement le plus récent de la Banque centrale européenne, majoré de 10 points"},"frais_mise_en_route":{"actif":true,"montant_ht":"190","offerts_paiement":"annuel","offres":["standard","premium"]},"droit_applicable":"francais","fournisseur_email":"Google Workspace (Google Ireland Limited, Gordon House, Barrow Street, Dublin 4, Irlande)","pied_email":"{nom_commercial} est un nom commercial de {denomination}, société immatriculée en {pays_immatriculation} ({registre}) sous le numéro {numero}. Siège : {siege}."};
// Anglais et néerlandais : même phrase que pied_texte_en et pied_texte_nl d'outils/legal.py (TRADUCTIONS, TRADUCTIONS_NL), avec la valeur française
// qu'elles traduisent. Si legal.json a changé sans que la traduction suive, le pied reste en français (jamais une valeur fausse) ; le test
// moteur/tests/test_courriels_langues.js compare ces phrases à celles d'outils/legal.py.
const PIED_FR = "{nom_commercial} est un nom commercial de {denomination}, société immatriculée en {pays_immatriculation} ({registre}) sous le numéro {numero}. Siège : {siege}.";
const PIED_LANGUES = {
  en: { gabarit: "{nom_commercial} is a trading name of {denomination}, a company registered in {pays_immatriculation} ({registre}) under number {numero}. Registered office: {siege}.",
    valeurs: { pays_immatriculation: ["Angleterre et au pays de Galles", "England and Wales"],
      siege: ["71-75 Shelton Street, Covent Garden, London WC2H 9JQ, Royaume-Uni", "71-75 Shelton Street, Covent Garden, London WC2H 9JQ, United Kingdom"] }, confidentialite: "Privacy: ", page: "/en/privacy.html" },
  nl: { gabarit: "{nom_commercial} is een handelsnaam van {denomination}, een vennootschap ingeschreven in {pays_immatriculation} ({registre}) onder nummer {numero}. Zetel: {siege}.",
    valeurs: { pays_immatriculation: ["Angleterre et au pays de Galles", "Engeland en Wales"],
      siege: ["71-75 Shelton Street, Covent Garden, London WC2H 9JQ, Royaume-Uni", "71-75 Shelton Street, Covent Garden, London WC2H 9JQ, Verenigd Koninkrijk"] }, confidentialite: "Privacy: ", page: "/nl/privacy.html" },
};
// Langue du pied : celle demandée si sa traduction est à jour de legal.json, sinon le français.
function langueDuPied(lg) {
  const t = PIED_LANGUES[langueEmail(lg)], s = LEGAL.societe;
  return t && LEGAL.pied_email === PIED_FR && Object.entries(t.valeurs).every(([k, [fr]]) => s[k] === fr) ? langueEmail(lg) : "fr";
}
function piedLegalTexte(lg) {
  const s = LEGAL.societe, p = langueDuPied(lg);
  if (p === "fr") return LEGAL.pied_email.replace(/\{(\w+)\}/g, (m, k) => k === "nom_commercial" ? LEGAL.nom_commercial : s[k]);
  const t = PIED_LANGUES[p];
  return t.gabarit.replace(/\{(\w+)\}/g, (m, k) => k === "nom_commercial" ? LEGAL.nom_commercial : t.valeurs[k] ? t.valeurs[k][1] : s[k]);
}
function lienConfidentialite(lg) {
  const u = String(LEGAL.site_url || "").replace(/\/+$/, ""), p = langueDuPied(lg);
  return /^https:\/\/[^\s"<>]+$/.test(u) ? u + (p === "fr" ? "/confidentialite.html" : PIED_LANGUES[p].page) : null;
}
const libelleConfidentialite = lg => langueDuPied(lg) === "fr" ? "Confidentialité : " : PIED_LANGUES[langueDuPied(lg)].confidentialite;
function piedLegalHtml(lg) { const u = lienConfidentialite(lg); return `${echapper(piedLegalTexte(lg))} ${libelleConfidentialite(lg)}${u ? lien(u, u) : "<strong>A_FOURNIR</strong>"}.`; }
const avecPied = (texte, lg) => texte + "\n\n" + piedLegalTexte(lg) + "\n" + libelleConfidentialite(lg) + (lienConfidentialite(lg) || "A_FOURNIR") + ".";

function page(titre, blocs, pied, lg) {
  return `<!doctype html><html lang="${HTML_LANG[langueEmail(lg)]}"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width"><title>${echapper(titre)}</title>
<style>@font-face{font-family:'Schibsted Grotesk';font-style:normal;font-weight:400 700;src:url(${POLICES_SITE}schibsted-grotesk.woff2) format('woff2')}</style></head>
<body style="margin:0;padding:0;background:${FOND};color:${ENCRE};font-family:${SANS_PAGE};font-size:16px;line-height:1.5">
<table role="presentation" width="100%" cellspacing="0" cellpadding="0" style="background:${FOND}"><tr><td align="center" style="padding:24px 16px">
<table role="presentation" width="100%" cellspacing="0" cellpadding="0" style="max-width:560px">
${blocs.join("\n")}
<tr><td style="padding-top:24px;border-top:1px solid ${FILET};color:${GRIS};font-size:13px">${pied}</td></tr>
<tr><td style="padding-top:12px;color:${GRIS};font-size:12px">${piedLegalHtml(lg)}</td></tr>
</table></td></tr></table></body></html>`;
}
const para = (html, style = "") => `<tr><td style="padding:0 0 16px 0;${style}">${html}</td></tr>`;

// ---- Mise en page commune des emails au commerçant (20/10/2026, demande de PJ : « un réel effort sur le design et le copywriting, autant que
// l'audit »). Charte du site (site/style.css, :root ; passée aux emails le 24/10/2026, demande de PJ : « le branding doit être le même partout ») et
// même charte que l'email de l'audit (moteur/audit/email_audit.py) : fond ivoire #F6F4EF, en-tête bleu nuit #0F1C3A, corps blanc ; bouton principal
// comme .btn-prim du site (aplat bleu nuit, texte ivoire 15,3:1, rayon 6 px, graisse 600) ; secondaire comme .btn-contour (contour bleu nuit) ;
// mot-symbole en texte comme l'en-tête sombre du site (« boostimpact » gras, point or champagne, « agency » normal), souligné d'un filet or fin
// en pleine largeur (en-tête de papier à lettres ; 26/10/2026, demande de PJ : troisième couleur de marque, accent rare). Titres en Source Serif 4,
// texte en Schibsted Grotesk, servies par boostimpact.agency (site/fonts), Georgia et Arial en repli (Gmail et Outlook ignorent les polices web) ;
// aucune image, aucun script ; tableaux et styles en ligne, 600 px et fluide ; couleurs de fond et de texte explicites sur chaque bloc ; color-scheme
// « light only ». Interdits : vert, orange, dégradé, majuscules d'étiquette, « → », trait coloré devant un libellé, mot isolé mis en relief dans un
// titre. Un seul bouton principal (bleu nuit) par email.
// Utilisée par bilanEmail et notificationEmail (ci-dessous), les emails de service au commerçant (service.js), l'alerte d'un commentaire sensible
// (commentaires/emails.js) et les modèles de Supabase Auth (courriels/supabase.js). Les emails à PJ gardent page() (alertes internes, sobres).
// Tout ce qui vient de la base passe par echapper() : les fonctions dont l'argument s'appelle « texte » échappent, celles qui prennent « html » non.
const MISE_EN_PAGE = (() => {
  // Jetons de site/style.css (:root) : nuit, carte, ivoire, blanc, doux, discret (discretN, sur fond nuit), ardoise, ardoise-clair, pierre (texteDiscret),
  // filet-clair (trait), filet-clair-fort (traitFort), texte doux #2E3443. Contrastes : ivoire sur nuit 15,3:1, doux sur nuit 12,9:1, discret sur nuit 7,9:1
  // (6,9:1 sur carte), ardoise clair sur nuit 9,8:1, pierre sur blanc 6,1:1 (5,5:1 sur ivoire), texte doux sur blanc 12,4:1.
  // Or champagne « or » (26/10/2026) : --or de site/style.css, seule définition côté JavaScript ; sur l'en-tête bleu nuit SEULEMENT (8,1:1 ; sur blanc
  // 2,1:1 et sur ivoire 1,9:1 : interdit), vérifié par moteur/tests/test_couleur_or.py.
  const C = { nuit: "#0F1C3A", carte: "#18284B", ivoire: "#F6F4EF", blanc: "#FFFFFF", doux: "#E3E1DA", discretN: "#AEB2BE", ardoise: "#3B5781",
    ardoiseClair: "#B9C6DD", clair: "#F6F4EF", surface: "#F6F4EF", texte: "#0F1C3A", texteDoux: "#2E3443", texteDiscret: "#5D6270", trait: "#D9DBE0",
    traitFort: "#B9BDC8", or: "#C4B385" };
  const SERIF = "'Source Serif 4',Georgia,'Times New Roman',serif", SANS = "'Schibsted Grotesk',Arial,Helvetica,sans-serif";
  const POLICES = "https://boostimpact.agency/fonts/";   // site/fonts, publiées avec le site
  // Mots communs : clôture (« notre équipe », jamais un prénom) et raison de l'envoi, dans la langue du commerce.
  const MOTS = {
    fr: { question: "Une question ? Répondez simplement à cet email : notre équipe vous répond.", equipe: "L'équipe BoostImpact",
      client: n => `Vous recevez cet email parce que ${n} est client de BoostImpact.`, stop: "Pour ne plus recevoir ces emails, décochez l'email dans les réglages de votre espace." },
    en: { question: "A question? Just reply to this email: our team will get back to you.", equipe: "The BoostImpact team",
      client: n => `You are receiving this email because ${n} is a BoostImpact customer.`, stop: "To stop receiving these emails, untick email in your account settings." },
    nl: { question: "Een vraag? Antwoord gewoon op deze e-mail: ons team helpt u verder.", equipe: "Het BoostImpact-team",
      client: n => `U ontvangt deze e-mail omdat ${n} klant is bij BoostImpact.`, stop: "Wilt u deze e-mails niet meer ontvangen, vink dan e-mail uit in de instellingen van uw klantenzone." },
  };
  const p = (html, o = {}) => `<p style="margin:${o.marge || "0 0 16px 0"};font-family:${SANS};font-size:${o.taille || 16}px;line-height:1.55;color:${o.couleur || C.texteDoux};${o.style || ""}">${html}</p>`;
  const h2 = (texte, marge = "12px 0 10px 0") => `<h2 style="margin:${marge};font-family:${SERIF};font-weight:400;font-size:28px;line-height:1.15;letter-spacing:-0.015em;color:${C.texte}">${echapper(texte)}</h2>`;
  const lienTexte = (href, texte, couleur = C.texte) => `<a href="${echapper(href)}" style="color:${couleur};text-decoration:underline;font-weight:600">${echapper(texte)}</a>`;
  const espace = h => `<div style="height:${h}px;line-height:${h}px;font-size:0">&nbsp;</div>`;
  // Bouton « à l'épreuve des clients mail » : une cellule colorée et un lien en bloc, comme .btn de site/style.css (rayon 6 px, graisse 600).
  // Principal (.btn-prim) : aplat bleu nuit, texte ivoire. Secondaire (.btn-contour) : fond blanc, contour et texte bleu nuit. o = {secondaire, marge}.
  function bouton(href, texte, o = {}) {
    const secondaire = !!o.secondaire, fond = secondaire ? C.blanc : C.nuit, encre = secondaire ? C.nuit : C.ivoire;
    return `<table role="presentation" cellpadding="0" cellspacing="0" border="0" style="border-collapse:separate;margin:${o.marge || "8px 0 28px 0"}"><tr>`
      + `<td bgcolor="${fond}" style="background-color:${fond};border:1px solid ${C.nuit};border-radius:6px;">`
      + `<a href="${echapper(href)}" style="display:inline-block;padding:${secondaire ? "11px 20px" : "14px 24px"};font-family:${SANS};font-size:${secondaire ? 15 : 16}px;font-weight:600;line-height:1.25;color:${encre};text-decoration:none;border-radius:6px">${echapper(texte)}</a>`
      + `</td></tr></table>`;
  }
  // Étapes d'une vraie séquence (mise en route) : numéro en serif, titre, aide. items = [{numero, titre, aide}].
  const etapes = items => items.map(x =>
    `<table role="presentation" width="100%" cellpadding="0" cellspacing="0" border="0" bgcolor="${C.surface}" style="background-color:${C.surface};border:1px solid ${C.trait};border-radius:8px;margin:0 0 12px 0"><tr>`
    + `<td width="44" valign="top" style="padding:16px 0 16px 18px;font-family:${SERIF};font-weight:400;font-size:34px;line-height:1;color:${C.texte}">${echapper(x.numero)}</td>`
    + `<td valign="top" style="padding:16px 18px 16px 8px">${p(echapper(x.titre), { marge: "0 0 4px 0", taille: 17, couleur: C.texte, style: "font-weight:600;line-height:1.3" })}`
    + `${x.aide ? p(echapper(x.aide), { marge: "0", taille: 15, style: "line-height:1.5" }) : ""}</td></tr></table>`).join("") + espace(8);
  // Lignes sans ordre : titre (en gras, sauf gras = false) et précision dessous, séparées par un filet. items = [[titre, precision]].
  const liste = (items, gras = true) => `<table role="presentation" width="100%" cellpadding="0" cellspacing="0" border="0" style="border-collapse:collapse;margin:0 0 24px 0">${items.map(([t, s]) =>
    `<tr><td style="padding:12px 0;border-top:1px solid ${C.trait}">${p(echapper(t), { marge: "0", couleur: gras ? C.texte : C.texteDoux, style: (gras ? "font-weight:600;" : "") + "line-height:1.5" })}`
    + `${s ? p(echapper(s), { marge: "2px 0 0 0", taille: 15, style: "line-height:1.5" }) : ""}</td></tr>`).join("")}</table>`;
  // Tableau libellé / valeur (chiffres du bilan, détail d'une alerte) : valeur à droite, en gras. Une valeur courte (un chiffre, « 4,5 sur 5 ») reste
  // sur une ligne ; une longue (« 0 (reçus et suivis par BoostImpact) », bilan dont la fiche n'a pas été lue) passe à la ligne : sur une ligne,
  // elle élargissait l'email à 401 px (493 px en néerlandais) pour un écran de 390 px (audit du 26/10/2026, constat 8).
  const lignes = rows => `<table role="presentation" width="100%" cellpadding="0" cellspacing="0" border="0" style="border-collapse:collapse;margin:0 0 20px 0">${rows.map(([l, v]) =>
    `<tr><td valign="top" style="padding:12px 12px 12px 0;border-top:1px solid ${C.trait};font-family:${SANS};font-size:15px;line-height:1.45;color:${C.texteDoux}">${echapper(l)}</td>`
    + `<td valign="top" align="right" style="padding:12px 0;border-top:1px solid ${C.trait};font-family:${SANS};font-size:16px;font-weight:600;line-height:1.45;color:${C.texte};${String(v).length > 16 ? "width:45%" : "white-space:nowrap"}">${echapper(v)}</td></tr>`).join("")}</table>`;
  // Encart sur fond clair : un titre en gras (facultatif) et un texte.
  const encart = (titre, html, marge = "0 0 24px 0") => `<table role="presentation" width="100%" cellpadding="0" cellspacing="0" border="0" bgcolor="${C.clair}" style="background-color:${C.clair};border-radius:8px;margin:${marge}"><tr><td style="padding:18px 20px">`
    + (titre ? p(echapper(titre), { marge: "0 0 4px 0", couleur: C.texte, style: "font-weight:600;line-height:1.4" }) : "") + html + `</td></tr></table>`;
  // Barre d'avancement en tableau (aucune image) : marine sur filet clair.
  function jauge(part, total) {
    const pct = Math.max(0, Math.min(100, Math.round(100 * part / total)));
    const cel = (pct ? [`<td width="${pct}%" bgcolor="${C.nuit}" style="background-color:${C.nuit};height:8px;line-height:8px;font-size:0;border-radius:4px">&nbsp;</td>`] : [])
      .concat(pct < 100 ? [`<td bgcolor="${C.trait}" style="background-color:${C.trait};height:8px;line-height:8px;font-size:0">&nbsp;</td>`] : []);
    return `<table role="presentation" width="100%" cellpadding="0" cellspacing="0" border="0" bgcolor="${C.trait}" style="background-color:${C.trait};border-radius:4px;table-layout:fixed;margin:0 0 24px 0"><tr>${cel.join("")}</tr></table>`;
  }
  // Élément à valider (ou commentaire cité) : sa nature en gras, l'extrait du texte en dessous, puis son action.
  const carte = (titre, extrait, actionHtml) => `<table role="presentation" width="100%" cellpadding="0" cellspacing="0" border="0" bgcolor="${C.surface}" style="background-color:${C.surface};border:1px solid ${C.trait};border-radius:8px;margin:0 0 12px 0"><tr><td style="padding:16px 18px">`
    + p(echapper(titre), { marge: extrait || actionHtml ? "0 0 4px 0" : "0", couleur: C.texte, style: "font-weight:600;line-height:1.35" })
    + (extrait ? p(echapper(extrait), { marge: actionHtml ? "0 0 10px 0" : "0", taille: 15, style: "line-height:1.5" }) : "") + (actionHtml || "") + `</td></tr></table>`;
  // Chiffres clés dans l'en-tête marine : [[libellé, valeur]], deux ou trois cases. Un chiffre en grand (serif) ; « non lue » en petit, sans relief.
  // Libellés sur une rangée (alignés en bas), valeurs sur la suivante (alignées en haut) : un libellé sur deux lignes (« Note Google au 1er octobre »)
  // ne décale plus sa valeur, les chiffres restent sur une même ligne (24/10/2026).
  const faits = f => `<table role="presentation" width="100%" cellpadding="0" cellspacing="0" border="0" bgcolor="${C.carte}" style="background-color:${C.carte};border-radius:8px;margin:24px 0 0 0;table-layout:fixed">`
    + `<tr>${f.map(([l]) => `<td valign="bottom" style="padding:14px 14px 4px 14px">${p(echapper(l), { marge: "0", taille: 13, couleur: C.discretN, style: "line-height:1.35" })}</td>`).join("")}</tr>`
    + `<tr>${f.map(([, v]) => `<td valign="top" style="padding:0 14px 14px 14px">`
    + (/^\d/.test(v) ? `<p style="margin:0;font-family:${SERIF};font-weight:400;font-size:30px;line-height:1.1;color:${C.ivoire}">${echapper(v)}</p>`
      : p(echapper(v), { marge: "6px 0 0 0", taille: 16, couleur: C.doux, style: "font-weight:600;line-height:1.3" })) + `</td>`).join("")}</tr></table>`;
  // Pied légal (site/legal.json) : mêmes phrases que le texte brut (avecPied), adresse de confidentialité cliquable.
  function legal(lg) {
    const u = lienConfidentialite(lg);
    return [echapper(piedLegalTexte(lg)), libelleConfidentialite(lg) + (u ? `<a href="${echapper(u)}" style="color:${C.texteDiscret};text-decoration:underline">${echapper(u)}</a>` : "<strong>A_FOURNIR</strong>") + "."];
  }
  // L'email entier. o = {lg, titre, apercu, repere (nom du commerce, en haut à droite), h1, chapo, faits, corps: [html], cloture (true par défaut),
  // pied: [texte], legal: langues du pied légal (par défaut celle de l'email ; ["fr", "en"] pour un modèle bilingue de Supabase)}.
  function courriel(o) {
    const lg = langueEmail(o.lg), M = MOTS[lg];
    const entete = `<tr><td class="px" bgcolor="${C.nuit}" style="background-color:${C.nuit};border-radius:8px 8px 0 0;padding:28px 32px 32px 32px">`
      + `<table role="presentation" width="100%" cellpadding="0" cellspacing="0" border="0" style="margin:0 0 26px 0"><tr>`
      + `<td valign="top" style="padding:0 0 18px 0;border-bottom:1px solid ${C.or};font-family:${SANS};font-size:24px;font-weight:700;letter-spacing:-0.03em;line-height:1;color:${C.ivoire}" translate="no">boostimpact<span style="color:${C.or}">.</span><span style="font-weight:400;letter-spacing:-0.01em;color:${C.discretN}">agency</span></td>`
      + (o.repere ? `<td valign="top" align="right" style="padding:3px 0 18px 16px;border-bottom:1px solid ${C.or};font-family:${SANS};font-size:14px;line-height:1.35;color:${C.discretN}">${echapper(o.repere)}</td>` : "")
      + `</tr></table>`
      + `<h1 class="h1" style="margin:0;font-family:${SERIF};font-weight:400;font-size:42px;line-height:1.05;letter-spacing:-0.02em;color:${C.ivoire}">${echapper(o.h1)}</h1>`
      + (o.chapo ? p(echapper(o.chapo), { marge: "14px 0 0 0", taille: 17, couleur: C.doux, style: "line-height:1.5" }) : "")
      + (o.faits && o.faits.length ? faits(o.faits) : "") + `</td></tr>`;
    const cloture = o.cloture === false ? "" : `<table role="presentation" width="100%" cellpadding="0" cellspacing="0" border="0" style="margin:8px 0 0 0"><tr><td style="padding:20px 0 0 0;border-top:1px solid ${C.trait}">`
      + p(echapper(M.question), { marge: "0 0 10px 0", taille: 15 }) + p(echapper(M.equipe), { marge: "0", couleur: C.texte, style: "font-weight:600" }) + `</td></tr></table>`;
    const corps = `<tr><td class="px" bgcolor="${C.blanc}" style="background-color:${C.blanc};border-radius:0 0 8px 8px;padding:32px 32px 28px 32px">${o.corps.filter(Boolean).join("")}${cloture}</td></tr>`;
    // Français : espace insécable avant « : ; ? ! » et à l'intérieur des guillemets, dans le texte seulement (jamais dans une balise ni une adresse).
    const typo = h => lg !== "fr" ? h : h.replace(/>([^<]+)</g, (m, x) => ">" + x.replace(/ ([:;?!»])/g, "\u00a0$1").replace(/« /g, "«\u00a0") + "<");
    const pied = `<tr><td class="px" style="padding:24px 32px 8px 32px">${[...(o.pied || []).map(echapper), ...(o.legal || [lg]).flatMap(legal)].map(x =>
      `<p style="margin:0 0 10px 0;font-family:${SANS};font-size:12px;line-height:1.5;color:${C.texteDiscret}">${x}</p>`).join("")}</td></tr>`;
    return `<!doctype html>\n<html lang="${HTML_LANG[lg]}"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1">`
      + `<meta name="x-apple-disable-message-reformatting"><meta name="color-scheme" content="light only"><meta name="supported-color-schemes" content="light only">`
      + `<title>${echapper(o.titre)}</title>\n<style>\n`
      + `@font-face{font-family:'Source Serif 4';font-style:normal;font-weight:400 600;src:url(${POLICES}source-serif-4.woff2) format('woff2')}\n`
      + `@font-face{font-family:'Schibsted Grotesk';font-style:normal;font-weight:400 700;src:url(${POLICES}schibsted-grotesk.woff2) format('woff2')}\n`
      + `h1,h2{font-variation-settings:'opsz' 48}\n`
      + `:root{color-scheme:light only;supported-color-schemes:light only}\n`
      + `a[x-apple-data-detectors]{color:inherit!important;text-decoration:none!important}\n`
      + `@media (max-width:480px){.px{padding-left:20px!important;padding-right:20px!important}.h1{font-size:36px!important}}\n`
      + `</style></head>\n<body style="margin:0;padding:0;background-color:${C.clair};color:${C.texte};-webkit-text-size-adjust:100%" bgcolor="${C.clair}">\n`
      + `<div style="display:none;max-height:0;max-width:0;overflow:hidden;opacity:0;mso-hide:all;color:${C.clair}">${echapper(o.apercu)}${"&#847;&zwnj;&nbsp;".repeat(40)}</div>\n`
      + `<table role="presentation" width="100%" cellpadding="0" cellspacing="0" border="0" bgcolor="${C.clair}" style="background-color:${C.clair}"><tr><td align="center" style="padding:24px 8px">\n`
      + `<table role="presentation" width="600" cellpadding="0" cellspacing="0" border="0" style="width:100%;max-width:600px">\n${typo(entete)}\n${typo(corps)}\n${pied}\n</table>\n`
      + `</td></tr></table>\n</body></html>\n`;
  }
  return { C, SERIF, SANS, POLICES, MOTS, p, h2, lienTexte, bouton, etapes, liste, lignes, encart, jauge, carte, faits, espace, courriel };
})();
const lien = (href, texte) => `<a href="${echapper(href)}" style="color:${ENCRE};text-decoration:underline">${echapper(texte)}</a>`;
function tableau(lignes) {
  return `<tr><td style="padding:0 0 16px 0"><table role="presentation" width="100%" cellspacing="0" cellpadding="0">${lignes.map(([l, v]) =>
    `<tr><td style="padding:10px 0;border-bottom:1px solid ${FILET}">${echapper(l)}</td><td align="right" style="padding:10px 0;border-bottom:1px solid ${FILET};font-weight:600">${echapper(v)}</td></tr>`).join("")}</table></td></tr>`;
}

// ---- Bilan du mois : b = résultat de bilan_mois_de(commerce, mois) (espace/supabase/schema.sql), complété par n8n avec la lecture de la fiche Google
// faite au moment de l'envoi (moteur/resultats/lecture_google.js, bilanGoogle : avis_obtenus_source « google »), et, quand ils sont lus (16/10/2026) :
//   b.performance = {appels, itineraires, clics_site, reservations} (performanceDuMois, API Business Profile Performance) : affiché seulement s'il est lu ;
//   b.themes = [{theme, positif, negatif}] (lireThemes, moteur/resultats/themes.js) : thèmes récurrents des avis du mois, seulement s'il y en a ;
//   b.ameliorations = [texte] : ce que l'équipe a écrit pour le mois suivant (facultatif).
// Fin du bilan, toujours : « Ce que nous avons fait. Ce qui évolue. Ce que nous améliorons le mois prochain. » Aucun chiffre inventé. commerce = {nom, langue}
const SOURCE_PERF = "https://support.google.com/business/answer/9918094?hl=fr";   // définitions des statistiques de la fiche, lues le 16/10/2026
// « de septembre », mais « d'octobre », « d'avril », « d'août » (20/10/2026 : le sujet disait « Votre bilan de octobre »).
const deMois = m => (/^[aeiouyàâäéèêëîïôöûüh]/i.test(m) ? "d'" : "de ") + m;
const TEXTES_BILAN = {
  fr: { nonLue: "non lue", note: v => v + " sur 5", nonLus: "non lus", avisBase: n => n + " (reçus et suivis par BoostImpact)", reponses: "Réponses aux avis publiées", publications: "Publications parues",
    noteAu: m => "Note Google au " + m, avisMois: "Avis obtenus dans le mois", appels: "Clics sur le bouton d'appel de votre fiche", itineraires: "Demandes d'itinéraire",
    clicsSite: "Clics vers votre site", reservations: "Réservations faites depuis votre fiche (Réserver avec Google)",
    perfNote: "Ces chiffres sont ceux de Google. Un clic n'est pas un appel abouti, ni une visite : Google compte le clic sur le bouton d'appel, pas l'appel lui-même ; une demande d'itinéraire n'est pas une venue.",
    compte: (p, n) => `${pluriel(p, "mention positive", "mentions positives")}, ${pluriel(n, "négative", "négatives")}`,
    baisse: "Votre note a baissé ce mois-ci : nous revoyons avec vous les avis négatifs et nos réponses.",
    themesNegatifs: neg => `Thème${neg.length > 1 ? "s" : ""} qui revien${neg.length > 1 ? "nent" : "t"} dans les avis négatifs : ${neg.join(", ")}. Nous en parlons avec vous avant le prochain bilan.`,
    rythme: "Nous gardons le rythme : chaque nouvel avis traité sous 24 h, vos contenus du mois proposés à temps.",
    attente: a => pluriel(a, "élément attend", "éléments attendent") + " votre validation.", attenteSuite: a => a > 1 ? "Une fois validés, ils paraissent." : "Une fois validé, il paraît.",
    rienAttente: "Rien n'attend votre validation.", sujet: (m, n) => `Votre bilan ${deMois(m)}, ${n}`,
    h1: m => `Votre bilan ${deMois(m)}.`, chapo: n => `Ce que nous avons fait pour ${n}, ce qui évolue et ce que nous améliorons.`,
    apercu: (r, p) => `${pluriel(r, "réponse publiée", "réponses publiées")} à vos avis, ${pluriel(p, "publication parue", "publications parues")}. Le détail du mois et la suite.`,
    fReponses: "Réponses aux avis", fPublications: "Publications", fNote: m => "Note Google au " + m,
    explicationGoogle: "Note et avis : calculés au moment de ce bilan à partir des avis présents sur votre fiche Google (un avis supprimé depuis n'est pas compté). Google ne permet pas à BoostImpact de les conserver.",
    explicationBase: "Avis obtenus : avis arrivés dans BoostImpact ce mois-ci. Votre fiche Google n'a pas pu être lue au moment de ce bilan : la note n'est pas donnée.",
