// Une seule ligne d'export : la copie dans n8n (n8n/build_*.py) retire les lignes qui commencent par « module.exports ».
// Alertes au commerçant par WhatsApp, et leur email de secours (décision de PJ du 22/10/2026). Recopié tel quel dans le nœud Code « Rédiger les
// messages » de n8n/renom-whatsapp.json, APRÈS moteur/courriels/courriels.js (les lignes « require » et « module.exports » sont retirées à la copie,
// n8n/build_whatsapp.py), et testé par moteur/tests/test_whatsapp.js. Données : un élément rendu par whatsapp_a_envoyer() (bloc « Alertes WhatsApp »
// de espace/supabase/schema.sql) : {id, type, canal, raison, numero, destinataire, commerce, langue, equipe_repond, note, auteur, reponse}.
// Trois alertes : avis_sensible (toutes offres), avis_traite (Standard et Premium : avis de 1 à 3 étoiles traité et publié par l'équipe),
// avis_a_valider (Essentiel : une réponse attend la validation). Textes courts et simples, FR, EN, NL (néerlandais de Belgique, « u »).
// Jamais le nom complet du client : prénom et initiale, comme Google l'affiche (« Camille D. »), réduits par la base (auteur_reduit) et ici encore.
// Jamais deux textes identiques envoyés à la suite (règle de PJ contre le blocage du numéro) : chaque message porte le nom du commerce, la note, le
// prénom et l'initiale, et pour « avis traité » un extrait de la réponse publiée.

// Règles d'envoi : mêmes valeurs que whatsapp_regles() de schema.sql (égalité testée par espace/supabase/test/rls.test.mjs).
const REGLES_WHATSAPP = {"ecart_min_secondes": 30, "alea_max_secondes": 15, "max_par_heure": 20, "heures_calmes": {"debut": 21, "fin": 8, "fuseau": "Europe/Paris"}, "attente_max_heures": 2, "fenetre_secondes": 300, "max_par_passage": 10};

const nettoyer = s => String(s == null ? "" : s).replace(/[\u0000-\u001f\u007f]+/g, " ").replace(/\s+/g, " ").trim();
// Prénom et initiale du nom (même règle que auteur_reduit de la base) : « Camille Dupont » -> « Camille D. » ; anonyme Google -> rien.
function prenomInitiale(nom) {
  const m = nettoyer(nom).split(" ").filter(Boolean);
  if (!m.length || ["un utilisateur google", "utilisateur google", "a google user", "google user"].includes(m.join(" ").toLowerCase())) return "";
  const init = m.length > 1 ? (Array.from(m[1]).find(ch => /\p{L}/u.test(ch)) || "") : "";
  return m[0] + (init ? " " + init.toUpperCase() + "." : "");
}
// Extrait de la réponse publiée : 160 caractères au plus, coupé à un mot, points de suspension.
function extrait(t, n = 160) {
  const x = nettoyer(t);
  if (x.length <= n) return x;
  const c = x.slice(0, n - 1), i = c.lastIndexOf(" ");
  return (i > n * 0.6 ? c.slice(0, i) : c).replace(/[\s,;:.!?-]+$/, "") + "…";
}
