const TYPES_ALERTE = ["avis_sensible", "avis_traite", "avis_a_valider"];

// Valeurs communes au WhatsApp et à l'email : nom du commerce, note, prénom et initiale, extrait, lien vers l'écran des avis de l'espace.
function valeurs(el, ctx) {
  const lg = langueEmail(el.langue), note = Number(el.note);
  if (!TYPES_ALERTE.includes(el.type)) throw new Error("type d'alerte inconnu : " + el.type);
  const commerce = nettoyer(el.commerce).replace(/["<>]/g, "");
  if (!commerce) throw new Error("nom du commerce absent : alerte non rédigée");
  if (el.type !== "avis_sensible" && !(note >= 1 && note <= 5)) throw new Error("note de l'avis absente : alerte non rédigée");
  return { lg, commerce, note: note >= 1 && note <= 5 ? note : null, etoiles: note >= 1 && note <= 5 ? ETOILES[lg](note) : "", qui: prenomInitiale(el.auteur),
    extrait: el.type === "avis_traite" ? extrait(el.reponse) : "", equipe_repond: el.equipe_repond === true, lien: adresse(ctx.urlEspace, "/#/avis") };
}

function texteWhatsapp(el, ctx) {
  const x = valeurs(el, ctx), T = TEXTES_WA[x.lg];
  return T[el.type](x).filter(Boolean).join("\n") + "\n\n" + T.signature;
}

function emailAlerte(el, ctx) {
  const x = valeurs(el, ctx), T = TEXTES_EMAIL[x.lg][el.type], M = MISE_EN_PAGE, mots = M.MOTS[x.lg];
  const sujet = T.sujet(x.commerce, x), ps = T.p(x).filter(Boolean), bonjour = { fr: "Bonjour,", en: "Hello,", nl: "Goeiedag," }[x.lg];
  const html = M.courriel({ lg: x.lg, titre: sujet, apercu: T.chapo, repere: x.commerce, h1: T.h1(x), chapo: T.chapo,
    corps: [M.p(echapper(bonjour), { couleur: M.C.texte }), ...ps.map(t => M.p(echapper(t))), M.bouton(x.lien, T.bouton)],
    pied: [mots.client(x.commerce)] });
  const texte = [bonjour, "", ...ps.flatMap(t => [t, ""]), T.bouton + (x.lg === "fr" ? " : " : ": ") + x.lien, "", mots.question, mots.equipe, "", mots.client(x.commerce)].join("\n");
  return { sujet, html, texte: avecPied(texte, x.lg) };
}

// Un élément de whatsapp_a_envoyer() -> ce que n8n envoie. canal « whatsapp » seulement si l'adresse de WaSender est posée (variable
// RENOM_WASENDER_URL, l'interrupteur) ET si la base a réservé un créneau WhatsApp ; sinon email (raison notée). Ni WhatsApp ni email possible :
// canal « aucun » (noté au journal, ALERTE_SANS_CANAL). L'email de secours est toujours préparé : il part si WaSender échoue.
function preparerAlerte(el, ctx) {
  const actif = /^https:\/\/[^\s"<>]+$/.test(String(ctx.wasenderUrl || "").trim());
  const wa = el.canal === "whatsapp" && actif && /^\+[1-9]\d{7,14}$/.test(el.numero || "");
  const email = /^[^\s@<>"]+@[^\s@<>"]+\.[^\s@<>"]{2,}$/.test(el.destinataire || "") ? Object.assign({ destinataire: el.destinataire }, emailAlerte(el, ctx)) : null;
  const raison = wa ? null : el.canal === "whatsapp" ? (actif ? "numero_invalide" : "wasender_non_branche") : (el.raison || "sans_whatsapp");
  return { id: el.id, type: el.type, canal: wa ? "whatsapp" : email ? "email" : "aucun", raison, creneau: el.creneau || null,
    whatsapp: wa ? { to: el.numero, text: texteWhatsapp(el, ctx) } : null, email };
}

// ---- Nœud « Rédiger les messages » : chaque alerte réservée par whatsapp_a_envoyer() -> ce qui part (WhatsApp et email de secours).
// Réponse de la base : une liste (n8n peut la rendre en un élément-liste ou en un élément par alerte : les deux sont lus). Une alerte impossible à
// rédiger part en « aucun canal », avec la raison (notée au journal, jamais renvoyée en boucle).
const ctx = {urlEspace: $vars.RENOM_URL_ESPACE, wasenderUrl: $vars.RENOM_WASENDER_URL};
const brut = $input.all().map(i => i.json), els = (brut.length === 1 && Array.isArray(brut[0]) ? brut[0] : brut).filter(x => x && x.id && x.type);
return els.map(el => { try { return {json: preparerAlerte(el, ctx)}; }
  catch (x) { return {json: {id: el.id, type: el.type, canal: 'aucun', raison: ('rédaction impossible : ' + String(x.message || x)).slice(0, 300), whatsapp: null, email: null}}; } });
